import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '../components/ui/Table'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { Wrench, Shield, Database, Globe, FileText, Settings, Play, ChevronRight } from 'lucide-react'
import { useState } from 'react'

const MOCK_TOOLS = [
  { name: 'aria_status', description: 'Return Aria version and operational status', tier: 0, category: 'Read' },
  { name: 'institutional_impulse_check', description: 'Check three-gate institutional impulse readiness', tier: 0, category: 'Read' },
  { name: 'value_proof_history', description: 'Get history of witnessed external value proofs', tier: 0, category: 'Read' },
  { name: 'giving_ledger', description: 'Measure recent giving — value delivered freely', tier: 0, category: 'Read' },
  { name: 'wedge_calibrator', description: 'Discover best value wedge from experience atoms', tier: 0, category: 'Read' },
  { name: 'task_backlog', description: 'Read current task backlog', tier: 0, category: 'Read' },
  { name: 'recent_reflections', description: 'Get recent weekly reflections and score trend', tier: 0, category: 'Read' },
  { name: 'hypothesis_queue', description: 'Get queue of open hypotheses', tier: 0, category: 'Read' },
  { name: 'risk_register', description: 'Read risk register', tier: 0, category: 'Read' },
  { name: 'git_week_summary', description: 'Get git activity summary', tier: 0, category: 'Read' },
  { name: 'record_proof_of_value', description: 'Record witnessed value delivery (T1)', tier: 1, category: 'Write' },
  { name: 'ask_aria', description: 'Ask Aria a question — full agent loop', tier: 1, category: 'Agent' },
]

export function Tools() {
  const { tools: mcpTools, connectionStatus } = useMCP()
  const [filter, setFilter] = useState<'all' | 'read' | 'write' | 'agent'>('all')
  const [search, setSearch] = useState('')
  
  const tools = MOCK_TOOLS.filter(t => {
    if (filter !== 'all' && filter !== t.category.toLowerCase()) return false
    if (search && !t.name.toLowerCase().includes(search.toLowerCase()) && !t.description.toLowerCase().includes(search.toLowerCase())) return false
    return true
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">MCP Tools</h1>
          <p className="text-aria-400 mt-1">Available tools exposed via Model Context Protocol</p>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="flex flex-col sm:flex-row gap-4">
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Filter:</label>
            <select 
              value={filter} 
              onChange={(e) => setFilter(e.target.value as typeof filter)}
              className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white focus:ring-2 focus:ring-kernel-safety/50"
            >
              <option value="all">All</option>
              <option value="read">Read (T0)</option>
              <option value="write">Write (T1)</option>
              <option value="agent">Agent</option>
            </select>
          </div>
          <div className="relative flex-1 max-w-md">
            <input
              type="text"
              placeholder="Search tools..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full bg-aria-800 border border-aria-700 rounded-lg px-10 py-2 text-sm text-white placeholder-aria-500 focus:ring-2 focus:ring-kernel-safety/50"
            />
            <Wrench className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-aria-500" aria-hidden="true" />
          </div>
        </CardContent>
      </Card>

      {/* Tools Table */}
      <Card>
        <CardContent className="p-0">
          {tools.length === 0 ? (
            <EmptyState icon={Wrench} title="No tools found" description="Adjust filters or check connection." />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">Tier</TableHead>
                  <TableHead>Name</TableHead>
                  <TableHead>Description</TableHead>
                  <TableHead className="w-32">Category</TableHead>
                  <TableHead className="w-48">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {tools.map(tool => (
                  <TableRow key={tool.name}>
                    <TableCell>
                      <Badge variant="tier" value={tool.tier}>T{tool.tier}</Badge>
                    </TableCell>
                    <TableCell className="font-mono text-sm font-medium">{tool.name}</TableCell>
                    <TableCell className="text-aria-300 max-w-md">{tool.description}</TableCell>
                    <TableCell>
                      <Badge variant="default">{tool.category}</Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-2">
                        <Button variant="ghost" size="sm" className="px-2 py-1">
                          <Play className="w-3 h-3" />
                        </Button>
                        <Button variant="ghost" size="sm" className="px-2 py-1">
                          <ChevronRight className="w-3 h-3" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Tier Legend */}
      <Card>
        <CardHeader>
          <CardTitle>Authority Tiers</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-5 gap-4">
            {[
              { tier: 0, label: 'Read-only', desc: 'No side effects', color: 'text-aria-400' },
              { tier: 1, label: 'Reversible', desc: 'Bounded scope, logged', color: 'text-blue-400' },
              { tier: 2, label: 'Persistent', desc: 'External calls, needs confirmation', color: 'text-yellow-400' },
              { tier: 3, label: 'Irreversible', desc: 'Financial/PII, explicit approval', color: 'text-orange-400' },
              { tier: 4, label: 'Cross-system', desc: 'Multi-agent, kill switch', color: 'text-kernel-safety' },
            ].map(t => (
              <div key={t.tier} className="p-4 rounded-lg bg-aria-800/50 border border-aria-700 text-center">
                <Badge variant="tier" value={t.tier} className="mb-2">T{t.tier}</Badge>
                <p className="font-medium text-white">{t.label}</p>
                <p className="text-xs text-aria-400">{t.desc}</p>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}