import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${seconds % 60}s`
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`
  return `${Math.floor(seconds / 86400)}d ${Math.floor((seconds % 86400) / 3600)}h`
}

export function formatTimestamp(isoString: string): string {
  const date = new Date(isoString)
  return date.toLocaleString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export function formatRelativeTime(isoString: string): string {
  const date = new Date(isoString)
  const now = new Date()
  const diffMs = now.getTime() - date.getTime()
  const diffSecs = Math.floor(diffMs / 1000)
  const diffMins = Math.floor(diffSecs / 60)
  const diffHours = Math.floor(diffMins / 60)
  const diffDays = Math.floor(diffHours / 24)
  
  if (diffSecs < 60) return 'just now'
  if (diffMins < 60) return `${diffMins}m ago`
  if (diffHours < 24) return `${diffHours}h ago`
  if (diffDays < 7) return `${diffDays}d ago`
  return formatTimestamp(isoString)
}

export function getSeverityColor(severity: string): string {
  switch (severity) {
    case 'critical': return 'text-kernel-safety bg-kernel-safety/10 border-kernel-safety/20'
    case 'high': return 'text-orange-400 bg-orange-400/10 border-orange-400/20'
    case 'medium': return 'text-yellow-400 bg-yellow-400/10 border-yellow-400/20'
    case 'low': return 'text-blue-400 bg-blue-400/10 border-blue-400/20'
    default: return 'text-aria-400 bg-aria-400/10 border-aria-400/20'
  }
}

export function getStatusColor(status: string): string {
  switch (status) {
    case 'ok': return 'text-kernel-flourishing bg-kernel-flourishing/10 border-kernel-flourishing/20'
    case 'warn': return 'text-yellow-400 bg-yellow-400/10 border-yellow-400/20'
    case 'error': return 'text-kernel-safety bg-kernel-safety/10 border-kernel-safety/20'
    case 'running': return 'text-kernel-flourishing bg-kernel-flourishing/10 border-kernel-flourishing/20'
    case 'paused': return 'text-yellow-400 bg-yellow-400/10 border-yellow-400/20'
    case 'completed': return 'text-blue-400 bg-blue-400/10 border-blue-400/20'
    case 'failed': return 'text-kernel-safety bg-kernel-safety/10 border-kernel-safety/20'
    default: return 'text-aria-400 bg-aria-400/10 border-aria-400/20'
  }
}

export function getTierColor(tier: number): string {
  switch (tier) {
    case 0: return 'text-aria-400'
    case 1: return 'text-blue-400'
    case 2: return 'text-yellow-400'
    case 3: return 'text-orange-400'
    case 4: return 'text-kernel-safety'
    default: return 'text-aria-400'
  }
}

export function getModeColor(mode: string): string {
  switch (mode) {
    case 'manual': return 'text-aria-400'
    case 'bounded': return 'text-yellow-400'
    case 'endurance': return 'text-kernel-flourishing'
    default: return 'text-aria-400'
  }
}

export function debounce<T extends (...args: unknown[]) => unknown>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: number
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => fn(...args), delay)
  }
}

export function throttle<T extends (...args: unknown[]) => unknown>(
  fn: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle = false
  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      fn(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }
}