import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Progress } from '../components/ui/Progress'
import { Button } from '../components/ui/Button'
import { Clock, Play, Pause, Plus, Minus, RotateCw, AlertTriangle, Zap, Target } from 'lucide-react'
import { formatDuration, getModeColor } from '../lib/utils'
import { useState } from 'react'

export function Timer() {
  const { timer, callTool, connectionStatus } = useMCP()
  const [extending, setExtending] = useState(false)
  
  const mockTimer = timer || {
    mode: 'endurance' as const,
    trust_tier: 3,
    lease_remaining_seconds: 14400, // 4 hours
    total_lease_seconds: 43200, // 12 hours
    is_paused: false,
    auto_extend: true,
  }

  const progress = ((mockTimer.total_lease_seconds - mockTimer.lease_remaining_seconds) / mockTimer.total_lease_seconds) * 100
  const hoursRemaining = Math.floor(mockTimer.lease_remaining_seconds / 3600)
  const minutesRemaining = Math.floor((mockTimer.lease_remaining_seconds % 3600) / 60)

  return (
    <div className="space-y-6 max-w-4xl">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Timer</h1>
          <p className="text-aria-400 mt-1">Unified timer system — Manual, Bounded, Endurance modes</p>
        </div>
      </div>

      {/* Main Timer Display */}
      <Card className="bg-gradient-to-br from-aria-900 via-aria-800 to-aria-900 border-aria-700">
        <CardContent className="py-8">
          <div className="text-center mb-8">
            <div className="flex items-center justify-center gap-4 mb-4">
              <Badge variant="mode" value={mockTimer.mode} className="text-lg px-4 py-2">
                {mockTimer.mode.charAt(0).toUpperCase() + mockTimer.mode.slice(1)}
              </Badge>
              <Badge variant="tier" value={mockTimer.trust_tier} className="text-lg px-4 py-2">
                Trust Tier {mockTimer.trust_tier}
              </Badge>
              {mockTimer.auto_extend && (
                <Badge variant="status" value="ok" className="text-lg px-4 py-2">
                  Auto-extend Enabled
                </Badge>
              )}
            </div>
            
            <div className="relative w-64 h-64 mx-auto mb-6">
              <svg className="w-full h-full transform -rotate-90">
                <circle
                  cx="128"
                  cy="128"
                  r="110"
                  fill="none"
                  stroke="#27272a"
                  strokeWidth="16"
                />
                <circle
                  cx="128"
                  cy="128"
                  r="110"
                  fill="none"
                  stroke="url(#timerGradient)"
                  strokeWidth="16"
                  strokeLinecap="round"
                  strokeDasharray={691.15}
                  strokeDashoffset={691.15 * (1 - progress / 100)}
                  style={{ transition: 'stroke-dashoffset 1s ease-out' }}
                />
                <defs>
                  <linearGradient id="timerGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                    <stop offset="0%" stopColor="#ef4444" />
                    <stop offset="50%" stopColor="#ec4899" />
                    <stop offset="100%" stopColor="#22c55e" />
                  </linearGradient>
                </defs>
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-5xl font-bold text-white font-mono tabular-nums">
                  {hoursRemaining.toString().padStart(2, '0')}:{minutesRemaining.toString().padStart(2, '0')}
                </span>
                <span className="text-aria-400 text-sm">Remaining</span>
              </div>
            </div>

            <Progress value={progress} max={100} variant="kernel" showLabel className="max-w-md mx-auto" />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-center">
            <div className="p-4 rounded-lg bg-aria-800/50">
              <p className="text-2xl font-bold text-white">{formatDuration(mockTimer.total_lease_seconds)}</p>
              <p className="text-sm text-aria-400">Total Lease</p>
            </div>
            <div className="p-4 rounded-lg bg-aria-800/50">
              <p className="text-2xl font-bold text-white">{formatDuration(mockTimer.lease_remaining_seconds)}</p>
              <p className="text-sm text-aria-400">Remaining</p>
            </div>
            <div className="p-4 rounded-lg bg-aria-800/50">
              <p className="text-2xl font-bold text-white">{formatDuration(mockTimer.total_lease_seconds - mockTimer.lease_remaining_seconds)}</p>
              <p className="text-sm text-aria-400">Elapsed</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Timer Controls */}
      <Card>
        <CardHeader>
          <CardTitle>Timer Controls</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-wrap gap-3">
            <Button variant={mockTimer.is_paused ? 'primary' : 'outline'} onClick={() => {}} disabled={connectionStatus !== 'connected'}>
              {mockTimer.is_paused ? <Play className="w-4 h-4 mr-2" /> : <Pause className="w-4 h-4 mr-2" />}
              {mockTimer.is_paused ? 'Resume' : 'Pause'}
            </Button>
            <Button variant="outline" onClick={() => setExtending(true)} disabled={connectionStatus !== 'connected'}>
              <Plus className="w-4 h-4 mr-2" />
              Extend Lease
            </Button>
            <Button variant="secondary" onClick={() => {}} disabled={connectionStatus !== 'connected'}>
              <RotateCw className="w-4 h-4 mr-2" />
              Re-arm Timer
            </Button>
            <Button variant="danger" onClick={() => {}} disabled={connectionStatus !== 'connected'}>
              <AlertTriangle className="w-4 h-4 mr-2" />
              Disarm
            </Button>
          </div>

          {extending && (
            <div className="p-4 rounded-lg bg-aria-800/50 border border-aria-700">
              <h4 className="font-medium text-white mb-3">Extend Timer Lease</h4>
              <div className="flex flex-wrap gap-3">
                {[1, 2, 4, 8, 12].map(hours => (
                  <Button key={hours} variant="outline" onClick={() => { setExtending(false); /* call extend */ }}>
                    +{hours}h
                  </Button>
                ))}
                <Button variant="ghost" onClick={() => setExtending(false)}>Cancel</Button>
              </div>
            </div>
          )}

          {/* Mode Selection */}
          <div className="pt-4 border-t border-aria-700">
            <h4 className="font-medium text-white mb-3">Re-arm with Mode</h4>
            <div className="grid grid-cols-3 gap-3">
              {[
                { mode: 'manual', label: 'Manual', desc: 'Human drives everything', tier: '—' },
                { mode: 'bounded', label: 'Bounded', desc: 'Work N hours, pause for approval', tier: '1-3' },
                { mode: 'endurance', label: 'Endurance', desc: 'Work until timer expires, auto-extend', tier: 'Up to 4' },
              ].map(m => (
                <Button 
                  key={m.mode} 
                  variant={mockTimer.mode === m.mode ? 'primary' : 'outline'} 
                  className="h-auto p-4 text-left justify-start"
                  onClick={() => {}}
                >
                  <div>
                    <p className="font-medium text-white">{m.label}</p>
                    <p className="text-xs text-aria-400">{m.desc}</p>
                    <p className="text-xs text-aria-500 mt-1">Tier ceiling: {m.tier}</p>
                  </div>
                </Button>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Timer Info */}
      <Card>
        <CardHeader>
          <CardTitle>Timer System Info</CardTitle>
        </CardHeader>
        <CardContent className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm">
          <InfoRow label="Timer Modes" value="Manual · Bounded · Endurance" />
          <InfoRow label="Auto-extend" value="1 hour at 5-minute warning boundary (Endurance only)" />
          <InfoRow label="Human Extend" value="Via `sov timer extend <hours>` or dashboard button" />
          <InfoRow label="CLI Commands" value="`sov timer status|arm|extend|disarm|pause|resume`" />
          <InfoRow label="Cockpit Display" value="Real-time countdown in status bar" />
          <InfoRow label="Trust Tier Ceiling" value="Manual: 1 · Bounded: 3 · Endurance: 4" />
        </CardContent>
      </Card>
    </div>
  )
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="p-3 rounded-lg bg-aria-800/30 border border-aria-700">
      <p className="text-aria-400 text-xs uppercase tracking-wider">{label}</p>
      <p className="text-white font-mono mt-1">{value}</p>
    </div>
  )
}