import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Progress } from '../components/ui/Progress'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { Skeleton, CardSkeleton } from '../components/ui/Skeleton'
import { 
  ShieldCheck, Activity, Clock, Award, Zap, ListTodo, 
  FlaskConical, BookOpen, GitBranch, AlertTriangle,
  TrendingUp, Target, Heart, Sparkles
} from 'lucide-react'
import { formatRelativeTime, getModeColor } from '../lib/utils'
import { useEffect, useState } from 'react'

const statCards = [
  { key: 'sentinels', label: 'Sentinels', icon: ShieldCheck, color: 'text-kernel-flourishing', bg: 'bg-kernel-flourishing/10' },
  { key: 'sessions', label: 'Active Sessions', icon: Activity, color: 'text-blue-400', bg: 'bg-blue-400/10' },
  { key: 'timer', label: 'Timer Lease', icon: Clock, color: 'text-yellow-400', bg: 'bg-yellow-400/10' },
  { key: 'proofs', label: 'Value Proofs', icon: Award, color: 'text-kernel-love', bg: 'bg-kernel-love/10' },
]

export function Dashboard() {
  const { 
    ariaStatus, 
    sentinels, 
    sessions, 
    timer, 
    proofs, 
    impulse,
    risks,
    backlog,
    hypotheses,
    refreshAll,
    connectionStatus,
    lastError
  } = useMCP()
  
  const [lastRefresh, setLastRefresh] = useState<Date | null>(null)
  const isLoading = connectionStatus === 'connecting'
  const isError = connectionStatus === 'error' || connectionStatus === 'disconnected'
  
  useEffect(() => {
    if (connectionStatus === 'connected') {
      refreshAll()
      setLastRefresh(new Date())
    }
  }, [connectionStatus, refreshAll])
  
  const sentinelOk = sentinels.filter(s => s.level === 'ok').length
  const sentinelWarn = sentinels.filter(s => s.level === 'warn').length
  const sentinelError = sentinels.filter(s => s.level === 'error').length
  const activeSessions = sessions.filter(s => s.status === 'running').length
  const criticalRisks = risks.filter(r => r.severity === 'critical' && r.status === 'open').length
  const pendingBacklog = backlog.filter(b => b.status === 'pending').length
  const openHypotheses = hypotheses.filter(h => h.status === 'open').length

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Dashboard</h1>
          <p className="text-aria-400 mt-1">Aria Sovereign Agent — Safety · Love · Flourishing</p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="secondary" size="sm" onClick={() => { refreshAll(); setLastRefresh(new Date()) }} disabled={connectionStatus !== 'connected'}>
            Refresh
          </Button>
          {lastRefresh && (
            <span className="text-xs text-aria-500 hidden sm:inline">
              Updated {formatRelativeTime(lastRefresh.toISOString())}
            </span>
          )}
        </div>
      </div>

      {/* Connection Status Banner */}
      {isError && (
        <Card className="border-kernel-safety/30 bg-kernel-safety/5">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="w-2 h-2 rounded-full bg-kernel-safety animate-pulse" />
              <div>
                <p className="font-medium text-kernel-safety">Connection Issue</p>
                <p className="text-sm text-aria-400">{lastError || 'Unable to connect to Aria MCP server. Retrying...'}</p>
              </div>
              <Button variant="ghost" size="sm" onClick={() => { refreshAll(); setLastRefresh(new Date()) }} className="ml-auto">
                Retry
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Kernel Status Bar */}
      <Card className="bg-gradient-to-r from-kernel-safety/10 via-kernel-love/10 to-kernel-flourishing/10 border-kernel-safety/20">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <Heart className="w-5 h-5 text-kernel-safety" aria-hidden="true" />
              <Sparkles className="w-5 h-5 text-kernel-love" aria-hidden="true" />
              <Target className="w-5 h-5 text-kernel-flourishing" aria-hidden="true" />
            </div>
            <div>
              <p className="font-semibold text-white">Kernel Status: Operational</p>
              <p className="text-sm text-aria-400">Safety · Love · Flourishing — All invariants holding</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <Badge variant="status" value="ok">System Healthy</Badge>
            {timer && (
              <Badge variant="mode" value={timer.mode}>
                {timer.mode.charAt(0).toUpperCase() + timer.mode.slice(1)} • Tier {timer.trust_tier}
              </Badge>
            )}
          </div>
        </div>
      </Card>

      {/* Stats Grid */}
      {isLoading ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card>
            <CardContent className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-kernel-flourishing/10 flex items-center justify-center">
                <ShieldCheck className="w-6 h-6 text-kernel-flourishing" aria-hidden="true" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{sentinelOk + sentinelWarn + sentinelError || ariaStatus?.sentinel_count || 0}</p>
                <p className="text-sm text-aria-400">Total Sentinels</p>
                <div className="flex items-center gap-2 mt-1">
                  <Badge variant="status" value="ok">{sentinelOk}</Badge>
                  <Badge variant="status" value="warn">{sentinelWarn}</Badge>
                  <Badge variant="status" value="error">{sentinelError}</Badge>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-blue-400/10 flex items-center justify-center">
                <Activity className="w-6 h-6 text-blue-400" aria-hidden="true" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{activeSessions}</p>
                <p className="text-sm text-aria-400">Active Sessions</p>
                <p className="text-xs text-aria-500">{sessions.length} total</p>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-yellow-400/10 flex items-center justify-center">
                <Clock className="w-6 h-6 text-yellow-400" aria-hidden="true" />
              </div>
              <div>
                {timer ? (
                  <>
                    <p className="text-2xl font-bold text-white">
                      {Math.floor(timer.lease_remaining_seconds / 3600)}h {Math.floor((timer.lease_remaining_seconds % 3600) / 60)}m
                    </p>
                    <p className="text-sm text-aria-400">Lease Remaining</p>
                    <Progress value={timer.total_lease_seconds - timer.lease_remaining_seconds} max={timer.total_lease_seconds} variant="kernel" className="mt-2" />
                  </>
                ) : (
                  <>
                    <p className="text-2xl font-bold text-aria-500">—</p>
                    <p className="text-sm text-aria-400">No active timer</p>
                  </>
                )}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-kernel-love/10 flex items-center justify-center">
                <Award className="w-6 h-6 text-kernel-love" aria-hidden="true" />
              </div>
              <div>
                <p className="text-3xl font-bold text-white">{proofs.length || 0}</p>
                <p className="text-sm text-aria-400">Value Proofs</p>
                <p className="text-xs text-aria-500">{impulse?.proof_gate ? 'Proof Gate: MET' : 'Proof Gate: PENDING'}</p>
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Impulse & Risks */}
        <div className="lg:col-span-2 space-y-6">
          {/* Institutional Impulse */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Zap className="w-5 h-5 text-kernel-love" aria-hidden="true" />
                Institutional Impulse Check
              </CardTitle>
              <CardDescription>Three-gate readiness for platform launch</CardDescription>
            </CardHeader>
            <CardContent>
              {impulse ? (
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <ImpulseGate 
                    label="Proof Gate" 
                    passed={impulse.proof_gate} 
                    description="≥1 external value proof"
                    icon={Award}
                  />
                  <ImpulseGate 
                    label="Signal Gate" 
                    passed={impulse.signal_gate} 
                    description={`Curiosity-driven (surprise: ${(impulse.avg_surprise * 100).toFixed(0)}%)`}
                    icon={TrendingUp}
                  />
                  <ImpulseGate 
                    label="Generation Gate" 
                    passed={impulse.generation_gate} 
                    description="Serves 7th generation"
                    icon={Target}
                  />
                </div>
              ) : (
                <EmptyState
                  icon={Zap}
                  title="Impulse check not loaded"
                  description="Connect to Aria to run the three-gate institutional impulse check."
                  action={<Button variant="outline" size="sm" onClick={refreshAll}>Refresh</Button>}
                />
              )}
              {impulse && (
                <div className={cn('mt-4 p-4 rounded-lg text-center font-medium', 
                  impulse.overall_readiness === 'ready' 
                    ? 'bg-kernel-flourishing/10 text-kernel-flourishing border border-kernel-flourishing/20'
                    : 'bg-kernel-safety/10 text-kernel-safety border border-kernel-safety/20'
                )}>
                  {impulse.overall_readiness === 'ready' ? (
                    '✓ READY FOR PLATFORM LAUNCH — All gates passed'
                  ) : (
                    `✗ NOT READY — ${impulse.primary_blocker || 'Gates not satisfied'}`
                  )}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Critical Risks */}
          {criticalRisks > 0 && (
            <Card>
              <CardHeader className="flex flex-row items-center justify-between">
                <CardTitle className="flex items-center gap-2">
                  <AlertTriangle className="w-5 h-5 text-kernel-safety" aria-hidden="true" />
                  Critical Risks ({criticalRisks})
                </CardTitle>
                <Button variant="ghost" size="sm">View All</Button>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {risks.filter(r => r.severity === 'critical' && r.status === 'open').slice(0, 3).map(risk => (
                    <div key={risk.id} className="p-3 rounded-lg bg-kernel-safety/5 border border-kernel-safety/10">
                      <p className="font-medium text-kernel-safety">{risk.title}</p>
                      <p className="text-sm text-aria-400 mt-1">{risk.description}</p>
                      {risk.mitigation && <p className="text-xs text-kernel-flourishing mt-1">Mitigation: {risk.mitigation}</p>}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Right Column - Quick Actions & Status */}
        <div className="space-y-6">
          {/* Quick Actions */}
          <Card>
            <CardHeader>
              <CardTitle>Quick Actions</CardTitle>
              <CardDescription>Common Aria operations</CardDescription>
            </CardHeader>
            <CardContent className="space-y-2">
              <QuickActionButton label="Run Impulse Check" icon={Zap} onClick={() => { /* call impulse check */ }} />
              <QuickActionButton label="Record Value Proof" icon={Award} onClick={() => { /* open proof modal */ }} />
              <QuickActionButton label="Check Sentinels" icon={ShieldCheck} onClick={() => { /* refresh sentinels */ }} />
              <QuickActionButton label="View Risk Register" icon={AlertTriangle} onClick={() => { /* navigate */ }} />
              <QuickActionButton label="Git Week Summary" icon={GitBranch} onClick={() => { /* navigate */ }} />
            </CardContent>
          </Card>

          {/* Timer Details */}
          {timer && (
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Clock className="w-5 h-5" style={{ color: getModeColor(timer.mode) }} aria-hidden="true" />
                  Timer Status
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="grid grid-cols-2 gap-4 text-center">
                  <div className="p-3 rounded-lg bg-aria-800/50">
                    <p className="text-2xl font-bold text-white">{Math.floor(timer.lease_remaining_seconds / 3600)}h</p>
                    <p className="text-xs text-aria-400">Hours</p>
                  </div>
                  <div className="p-3 rounded-lg bg-aria-800/50">
                    <p className="text-2xl font-bold text-white">{Math.floor((timer.lease_remaining_seconds % 3600) / 60)}m</p>
                    <p className="text-xs text-aria-400">Minutes</p>
                  </div>
                </div>
                <Progress 
                  value={timer.total_lease_seconds - timer.lease_remaining_seconds} 
                  max={timer.total_lease_seconds} 
                  variant="kernel"
                  showLabel
                />
                <div className="flex items-center justify-between text-sm">
                  <Badge variant="mode" value={timer.mode}>
                    {timer.mode.charAt(0).toUpperCase() + timer.mode.slice(1)}
                  </Badge>
                  <Badge variant="tier" value={timer.trust_tier}>
                    Tier {timer.trust_tier}
                  </Badge>
                  {timer.auto_extend && (
                    <Badge variant="status" value="ok">Auto-extend enabled</Badge>
                  )}
                </div>
              </CardContent>
            </Card>
          )}

          {/* Backlog Summary */}
          {(pendingBacklog > 0 || openHypotheses > 0) && (
            <Card>
              <CardHeader>
                <CardTitle>Work Overview</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <StatRow label="Pending Backlog" value={pendingBacklog} icon={ListTodo} color="text-blue-400" />
                <StatRow label="Open Hypotheses" value={openHypotheses} icon={FlaskConical} color="text-purple-400" />
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  )
}

function ImpulseGate({ label, passed, description, icon: Icon }: { 
  label: string; 
  passed: boolean; 
  description: string; 
  icon: React.ComponentType<{ className?: string }> 
}) {
  return (
    <div className={cn('p-4 rounded-lg border text-center', 
      passed 
        ? 'bg-kernel-flourishing/10 border-kernel-flourishing/20' 
        : 'bg-kernel-safety/10 border-kernel-safety/20'
    )}>
      <div className="flex items-center justify-center gap-2 mb-2">
        <Icon className={cn('w-5 h-5', passed ? 'text-kernel-flourishing' : 'text-kernel-safety')} aria-hidden="true" />
        <span className="font-medium text-white">{label}</span>
      </div>
      <Badge variant="status" value={passed ? 'ok' : 'error'} className="mb-2">
        {passed ? 'PASSED' : 'BLOCKED'}
      </Badge>
      <p className="text-xs text-aria-400">{description}</p>
    </div>
  )
}

function QuickActionButton({ label, icon: Icon, onClick }: { label: string; icon: React.ComponentType<{ className?: string }>; onClick: () => void }) {
  return (
    <button onClick={onClick} className="w-full flex items-center gap-3 p-3 rounded-lg bg-aria-800/50 border border-aria-700 hover:border-aria-600 hover:bg-aria-800 transition-colors text-left">
      <Icon className="w-5 h-5 text-aria-400" aria-hidden="true" />
      <span className="text-sm text-aria-300 font-medium">{label}</span>
    </button>
  )
}

function StatRow({ label, value, icon: Icon, color }: { label: string; value: number; icon: React.ComponentType<{ className?: string }>; color: string }) {
  return (
    <div className="flex items-center gap-3 p-2 rounded-lg bg-aria-800/30">
      <Icon className={cn('w-5 h-5', color)} aria-hidden="true" />
      <span className="text-sm text-aria-300 flex-1">{label}</span>
      <Badge variant="default">{value}</Badge>
    </div>
  )
}

import { cn } from '../lib/utils'