import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { BookOpen, Plus, TrendingUp, Target, Heart, Star, RefreshCw, Calendar } from 'lucide-react'
import { formatRelativeTime, formatTimestamp } from '../lib/utils'
import { useState } from 'react'

export function Reflections() {
  const { reflections, refreshReflections, connectionStatus } = useMCP()
  const [selectedReflection, setSelectedReflection] = useState<string | null>(null)

  const mockReflections = [
    { 
      id: 'refl_001', 
      period: 'Week 31, 2026', 
      score: 8.5, 
      highlights: ['Endurance timer system deployed successfully', 'Subtask fallback prevents session death', 'Circuit breaker tools operational'], 
      challenges: ['VRAM limits on 8GB GPU', 'SSE connection drops under load'], 
      next_focus: ['Cloudflare tunnel setup', 'Web dashboard MVP', 'Site generator CLI'], 
      created_at: new Date(Date.now() - 86400000).toISOString() 
    },
    { 
      id: 'refl_002', 
      period: 'Week 30, 2026', 
      score: 7.0, 
      highlights: ['Aria workspace venv created', 'Background update system live', 'Threading enforcement implemented'], 
      challenges: ['divmod float bug in cockpit', 'TimerMode import missing'], 
      next_focus: ['Endurance mode decomposition', 'Session resilience', 'Production deploy prep'], 
      created_at: new Date(Date.now() - 604800000).toISOString() 
    },
    { 
      id: 'refl_003', 
      period: 'Week 29, 2026', 
      score: 6.5, 
      highlights: ['Unified timer system designed', 'MCP server stabilized', 'Key concierge expanded'], 
      challenges: ['Session ending after 1 subtask', 'No fallback mechanism'], 
      next_focus: ['Unified timer implementation', 'Session resilience', 'Circuit breaker improvements'], 
      created_at: new Date(Date.now() - 1209600000).toISOString() 
    },
  ]

  const avgScore = mockReflections.reduce((sum, r) => sum + r.score, 0) / mockReflections.length
  const trend = mockReflections.length >= 2 ? mockReflections[0].score - mockReflections[1].score : 0

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Weekly Reflections</h1>
          <p className="text-aria-400 mt-1">Retrospective practice — breathing: insight in, regret out</p>
        </div>
        <Button variant="primary"><Plus className="w-4 h-4 mr-2" /> New Reflection</Button>
      </div>

      {/* Score Summary */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card className="bg-gradient-to-r from-kernel-safety/10 via-kernel-love/10 to-kernel-flourishing/10 border-aria-700">
          <CardContent className="flex items-center justify-between p-6">
            <div>
              <p className="text-4xl font-bold text-white">{avgScore.toFixed(1)}</p>
              <p className="text-sm text-aria-400">Average Score</p>
            </div>
            <div className="text-center">
              <div className="w-20 h-20 rounded-full border-4 border-kernel-flourishing/30 flex items-center justify-center">
                <TrendingUp className="w-8 h-8 text-kernel-flourishing" />
              </div>
            </div>
            <div className="text-right">
              <p className={cn('text-2xl font-bold', trend >= 0 ? 'text-kernel-flourishing' : 'text-kernel-safety')}>
                {trend >= 0 ? '+' : ''}{trend.toFixed(1)}
              </p>
              <p className="text-sm text-aria-400">Week-over-week</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6 text-center">
            <p className="text-4xl font-bold text-white">{mockReflections.length}</p>
            <p className="text-sm text-aria-400">Total Reflections</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6 text-center">
            <p className="text-4xl font-bold text-white">{mockReflections.filter(r => r.score >= 8).length}</p>
            <p className="text-sm text-aria-400">High Score Weeks (≥8)</p>
          </CardContent>
        </Card>
      </div>

      {/* Reflections List */}
      <Card>
        <CardContent className="p-0">
          {mockReflections.length === 0 ? (
            <EmptyState icon={BookOpen} title="No reflections recorded" description="Start the weekly reflective practice." action={<Button variant="primary"><Plus className="w-4 h-4 mr-2" /> Write First Reflection</Button>} />
          ) : (
            <div className="divide-y divide-aria-800">
              {mockReflections.map(reflection => (
                <div key={reflection.id} className={cn('p-6 transition-colors', selectedReflection === reflection.id ? 'bg-aria-800/30' : 'hover:bg-aria-800/30')} onClick={() => setSelectedReflection(selectedReflection === reflection.id ? null : reflection.id)}>
                  <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-14 h-14 rounded-xl bg-gradient-to-br from-kernel-safety via-kernel-love to-kernel-flourishing flex items-center justify-center">
                        <BookOpen className="w-7 h-7 text-white" />
                      </div>
                      <div>
                        <h3 className="font-semibold text-white">{reflection.period}</h3>
                        <p className="text-sm text-aria-400">{formatTimestamp(reflection.created_at)}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                      <div className={cn('text-3xl font-bold', reflection.score >= 8 ? 'text-kernel-flourishing' : reflection.score >= 6 ? 'text-yellow-400' : 'text-kernel-safety')}>
                        {reflection.score}/10
                      </div>
                      <Button variant="ghost" size="sm" onClick={e => { e.stopPropagation(); setSelectedReflection(selectedReflection === reflection.id ? null : reflection.id) }}>
                        {selectedReflection === reflection.id ? 'Collapse' : 'Expand'}
                      </Button>
                    </div>
                  </div>

                  {selectedReflection === reflection.id && (
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-4 border-t border-aria-700">
                      <div>
                        <h4 className="font-medium text-white mb-2 flex items-center gap-2"><TrendingUp className="w-4 h-4 text-kernel-flourishing" /> Highlights</h4>
                        <ul className="space-y-1">
                          {reflection.highlights.map((h, i) => (
                            <li key={i} className="text-sm text-aria-300 flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-kernel-flourishing" />{h}</li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <h4 className="font-medium text-white mb-2 flex items-center gap-2"><Target className="w-4 h-4 text-kernel-safety" /> Challenges</h4>
                        <ul className="space-y-1">
                          {reflection.challenges.map((c, i) => (
                            <li key={i} className="text-sm text-aria-300 flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-kernel-safety" />{c}</li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <h4 className="font-medium text-white mb-2 flex items-center gap-2"><Heart className="w-4 h-4 text-kernel-love" /> Next Focus</h4>
                        <ul className="space-y-1">
                          {reflection.next_focus.map((f, i) => (
                            <li key={i} className="text-sm text-aria-300 flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-kernel-love" />{f}</li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Reflection Template */}
      <Card className="bg-kernel-love/5 border-kernel-love/20">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BookOpen className="w-5 h-5 text-kernel-love" />
            Reflection Template
          </CardTitle>
          <CardDescription>The Lungs — breathing practice for the system</CardDescription>
        </CardHeader>
        <CardContent className="grid grid-cols-1 md:grid-cols-4 gap-4 text-sm">
          <TemplateSection title="Ingest" icon="📥" items={['What happened this week?', 'What data/feedback received?', 'What was assumed?']} />
          <TemplateSection title="Guardrails" icon="🛡️" items={['Safety checks passed?', 'Scope limits respected?', 'Authority constraints honored?']} />
          <TemplateSection title="Signal Check" icon="📡" items={['Pattern or fear?', 'What would invert my view?', 'Calibrated uncertainty?']} />
          <TemplateSection title="Horizon" icon="🔮" items={['3-month projection', '7th-generation check', 'Single best forward path']} />
        </CardContent>
      </Card>
    </div>
  )
}

function TemplateSection({ title, icon, items }: { title: string; icon: string; items: string[] }) {
  return (
    <div className="p-4 rounded-lg bg-aria-800/50 border border-aria-700">
      <div className="flex items-center gap-2 mb-3">
        <span className="text-xl">{icon}</span>
        <h5 className="font-medium text-white">{title}</h5>
      </div>
      <ul className="space-y-1">
        {items.map((item, i) => (
          <li key={i} className="text-xs text-aria-400 flex items-center gap-1">
            <span className="w-1 h-1 rounded-full bg-aria-500" />
            {item}
          </li>
        ))}
      </ul>
    </div>
  )
}

import { cn } from '../lib/utils'