import { Routes, Route, useLocation } from 'react-router-dom'
import { Layout } from './components/Layout'
import { PublicLayout } from './components/PublicLayout'
import { AuthProvider } from './context/AuthContext'
import { ProtectedRoute } from './components/ProtectedRoute'
import { Dashboard } from './pages/Dashboard'
import { Sentinels } from './pages/Sentinels'
import { Tools } from './pages/Tools'
import { Sessions } from './pages/Sessions'
import { Timer } from './pages/Timer'
import { Risks } from './pages/Risks'
import { Proofs } from './pages/Proofs'
import { Impulse } from './pages/Impulse'
import { Backlog } from './pages/Backlog'
import { Hypotheses } from './pages/Hypotheses'
import { Reflections } from './pages/Reflections'
import { GitSummary } from './pages/GitSummary'
import { Support } from './pages/Support'
import { Users } from './pages/Users'
import { GRC } from './pages/GRC'
import { LoginPage } from './pages/auth/LoginPage'
import { RegisterPage } from './pages/auth/RegisterPage'
import { HomePage } from './pages/public/HomePage'
import { ServicesPage } from './pages/public/ServicesPage'
import { AboutPage } from './pages/public/AboutPage'
import { ContactPage } from './pages/public/ContactPage'
import { NotFoundPage } from './pages/public/NotFoundPage'

const dashboardNavItems = [
  { path: '/dashboard', label: 'Dashboard', icon: 'LayoutDashboard' },
  { path: '/dashboard/support', label: 'Support', icon: 'MessageSquare' },
  { path: '/dashboard/sentinels', label: 'Sentinels', icon: 'ShieldCheck' },
  { path: '/dashboard/tools', label: 'Tools', icon: 'Wrench' },
  { path: '/dashboard/sessions', label: 'Sessions', icon: 'Activity' },
  { path: '/dashboard/timer', label: 'Timer', icon: 'Clock' },
  { path: '/dashboard/risks', label: 'Risks', icon: 'AlertTriangle' },
  { path: '/dashboard/proofs', label: 'Proofs', icon: 'Award' },
  { path: '/dashboard/impulse', label: 'Impulse', icon: 'Zap' },
  { path: '/dashboard/backlog', label: 'Backlog', icon: 'ListTodo' },
  { path: '/dashboard/hypotheses', label: 'Hypotheses', icon: 'FlaskConical' },
  { path: '/dashboard/reflections', label: 'Reflections', icon: 'BookOpen' },
  { path: '/dashboard/git', label: 'Git Summary', icon: 'GitBranch' },
  { path: '/dashboard/users', label: 'Users', icon: 'Users' },
  { path: '/dashboard/grc', label: 'GRC', icon: 'Shield' },
]

function DashboardRoutes() {
  const location = useLocation()
  const currentPath = location.pathname.replace('/dashboard', '') || '/'

  return (
    <Layout navItems={dashboardNavItems} currentPath={currentPath}>
      <Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/support" element={<Support />} />
        <Route path="/sentinels" element={<Sentinels />} />
        <Route path="/tools" element={<Tools />} />
        <Route path="/sessions" element={<Sessions />} />
        <Route path="/timer" element={<Timer />} />
        <Route path="/risks" element={<Risks />} />
        <Route path="/proofs" element={<Proofs />} />
        <Route path="/impulse" element={<Impulse />} />
        <Route path="/backlog" element={<Backlog />} />
        <Route path="/hypotheses" element={<Hypotheses />} />
        <Route path="/reflections" element={<Reflections />} />
        <Route path="/git" element={<GitSummary />} />
        <Route path="/users" element={<Users />} />
        <Route path="/grc" element={<GRC />} />
      </Routes>
    </Layout>
  )
}

export function App() {
  return (
    <AuthProvider>
      <Routes>
        {/* Public routes */}
        <Route element={<PublicLayout />}>
          <Route path="/" element={<HomePage />} />
          <Route path="/services" element={<ServicesPage />} />
          <Route path="/about" element={<AboutPage />} />
          <Route path="/contact" element={<ContactPage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />
        </Route>

        {/* Protected dashboard routes */}
        <Route
          path="/dashboard/*"
          element={
            <ProtectedRoute>
              <DashboardRoutes />
            </ProtectedRoute>
          }
        />

        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </AuthProvider>
  )
}