import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Progress } from '../components/ui/Progress'
import { Button } from '../components/ui/Button'
import { Zap, Award, Target, TrendingUp, Shield, CheckCircle, XCircle, RefreshCw, Heart } from 'lucide-react'

export function Impulse() {
  const { impulse, refreshImpulse, connectionStatus } = useMCP()

  const mockImpulse = impulse || {
    proof_gate: true,
    signal_gate: true,
    generation_gate: false,
    overall_readiness: 'not_ready',
    primary_blocker: 'Generation gate not satisfied — current work serves quarterly goals, not 7th generation',
    guidance: 'Refocus current session on long-term flourishing vectors. Consider: Does this serve life getting better for the 7th generation?',
    avg_surprise: 0.67,
  }

  const gates = [
    { 
      key: 'proof_gate', 
      label: 'Proof Gate', 
      passed: mockImpulse.proof_gate, 
      icon: Award, 
      description: '≥1 external (non-builder) value proof witnessed',
      detail: 'Aria has helped at least one external person solve a real problem without being asked.',
      check: () => mockImpulse.proof_gate
    },
    { 
      key: 'signal_gate', 
      label: 'Signal Gate', 
      passed: mockImpulse.signal_gate, 
      icon: TrendingUp, 
      description: 'Curiosity-driven (avg_surprise > 0.4), not fear-reactive',
      detail: `Current avg_surprise: ${(mockImpulse.avg_surprise * 100).toFixed(0)}% — work is driven by genuine curiosity and discovery.`,
      check: () => mockImpulse.signal_gate
    },
    { 
      key: 'generation_gate', 
      label: 'Generation Gate', 
      passed: mockImpulse.generation_gate, 
      icon: Target, 
      description: 'Serves 7th generation flourishing, not just this quarter',
      detail: 'Current trajectory optimizes for short-term metrics. Need to align with intergenerational equity.',
      check: () => mockImpulse.generation_gate
    },
  ]

  return (
    <div className="space-y-6 max-w-4xl">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Institutional Impulse</h1>
          <p className="text-aria-400 mt-1">Three-gate readiness check for platform launch decisions</p>
        </div>
        <Button variant="outline" onClick={refreshImpulse} disabled={connectionStatus !== 'connected'}><RefreshCw className="w-4 h-4 mr-2" /> Refresh</Button>
      </div>

      {/* Overall Status */}
      <Card className={cn(
        'border-2',
        mockImpulse.overall_readiness === 'ready'
          ? 'border-kernel-flourishing bg-gradient-to-r from-kernel-flourishing/5 via-transparent to-kernel-love/5'
          : 'border-kernel-safety bg-gradient-to-r from-kernel-safety/5 via-transparent to-kernel-love/5'
      )}>
        <CardContent className="py-8">
          <div className="text-center mb-6">
            <div className={cn('inline-flex items-center gap-3 px-6 py-3 rounded-full text-lg font-medium',
              mockImpulse.overall_readiness === 'ready'
                ? 'bg-kernel-flourishing/20 text-kernel-flourishing border border-kernel-flourishing/30'
                : 'bg-kernel-safety/20 text-kernel-safety border border-kernel-safety/30'
            )}>
              {mockImpulse.overall_readiness === 'ready' ? (
                <>
                  <CheckCircle className="w-5 h-5" />
                  READY FOR PLATFORM LAUNCH
                </>
              ) : (
                <>
                  <XCircle className="w-5 h-5" />
                  NOT READY
                </>
              )}
            </div>
          </div>
          
          <Progress 
            value={gates.filter(g => g.check()).length} 
            max={3} 
            variant="kernel" 
            showLabel 
            className="max-w-md mx-auto mb-6"
          />
          
          <p className="text-aria-300 text-center max-w-2xl mx-auto">
            {mockImpulse.overall_readiness === 'ready' 
              ? 'All three gates satisfied. Institutional impulse authorized for platform launch.'
              : `Blocked: ${mockImpulse.primary_blocker || 'Gates not satisfied'}`
            }
          </p>
        </CardContent>
      </Card>

      {/* Three Gates */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {gates.map((gate, index) => (
          <Card key={gate.key} className={cn('relative overflow-hidden', gate.passed ? 'border-kernel-flourishing/30' : 'border-kernel-safety/30')}>
            <div className={cn('absolute top-0 left-0 right-0 h-1', gate.passed ? 'bg-gradient-to-r from-kernel-safety via-kernel-love to-kernel-flourishing' : 'bg-kernel-safety/30')} />
            <CardContent className="pt-6">
              <div className="flex items-center gap-3 mb-4">
                <div className={cn('w-12 h-12 rounded-xl flex items-center justify-center', gate.passed ? 'bg-kernel-flourishing/10' : 'bg-kernel-safety/10')}>
                  <gate.icon className={cn('w-6 h-6', gate.passed ? 'text-kernel-flourishing' : 'text-kernel-safety')} />
                </div>
                <div>
                  <h3 className="font-semibold text-white">{gate.label}</h3>
                  <Badge variant="status" value={gate.passed ? 'ok' : 'error'}>{gate.passed ? 'PASSED' : 'BLOCKED'}</Badge>
                </div>
              </div>
              <p className="text-sm text-aria-400 mb-3">{gate.description}</p>
              <p className="text-xs text-aria-500">{gate.detail}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Guidance */}
      <Card className="bg-kernel-love/5 border-kernel-love/20">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Zap className="w-5 h-5 text-kernel-love" />
            Guidance
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-aria-300">{mockImpulse.guidance}</p>
        </CardContent>
      </Card>

      {/* Kernel Reference */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Shield className="w-5 h-5 text-kernel-safety" />
            Kernel Reference
          </CardTitle>
        </CardHeader>
        <CardContent className="grid grid-cols-3 gap-4 text-center">
          <div className="p-4 rounded-lg bg-kernel-safety/10 border border-kernel-safety/20">
            <div className="w-10 h-10 mx-auto mb-2 rounded-full bg-kernel-safety/20 flex items-center justify-center">
              <Shield className="w-5 h-5 text-kernel-safety" />
            </div>
            <p className="font-medium text-white">Safety</p>
            <p className="text-xs text-aria-400">Never irreversible without approval</p>
          </div>
          <div className="p-4 rounded-lg bg-kernel-love/10 border border-kernel-love/20">
            <div className="w-10 h-10 mx-auto mb-2 rounded-full bg-kernel-love/20 flex items-center justify-center">
              <Heart className="w-5 h-5 text-kernel-love" />
            </div>
            <p className="font-medium text-white">Love</p>
            <p className="text-xs text-aria-400">Act from care, serve 7th generation</p>
          </div>
          <div className="p-4 rounded-lg bg-kernel-flourishing/10 border border-kernel-flourishing/20">
            <div className="w-10 h-10 mx-auto mb-2 rounded-full bg-kernel-flourishing/20 flex items-center justify-center">
              <Target className="w-5 h-5 text-kernel-flourishing" />
            </div>
            <p className="font-medium text-white">Flourishing</p>
            <p className="text-xs text-aria-400">Build for life to get better</p>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

import { cn } from '../lib/utils'