import { cn } from '../../lib/utils'

interface SkeletonProps {
  className?: string
  variant?: 'text' | 'circular' | 'rectangular'
  width?: string | number
  height?: string | number
}

export function Skeleton({ className, variant = 'rectangular', width, height }: SkeletonProps) {
  return (
    <div
      className={cn(
        'animate-pulse bg-aria-800',
        variant === 'text' && 'h-4 rounded',
        variant === 'circular' && 'rounded-full',
        variant === 'rectangular' && 'rounded-lg',
        className
      )}
      style={{
        width: width || '100%',
        height: height || (variant === 'text' ? '1rem' : '100%'),
      }}
    />
  )
}

export function CardSkeleton() {
  return (
    <div className="rounded-xl border border-aria-800 bg-aria-900/50 p-6 space-y-4">
      <Skeleton variant="rectangular" height={120} />
      <Skeleton variant="text" height={24} width="60%" />
      <Skeleton variant="text" height={16} width="80%" />
    </div>
  )
}

export function TableRowSkeleton() {
  return (
    <div className="flex items-center gap-4 p-4 border-b border-aria-800">
      <Skeleton variant="rectangular" height={40} width={40} />
      <div className="flex-1 space-y-2">
        <Skeleton variant="text" height={16} width="70%" />
        <Skeleton variant="text" height={12} width="40%" />
      </div>
    </div>
  )
}