import { useState, useEffect, useCallback, useRef } from 'react'
import type { DashboardState, SentinelHealth, RiskItem, ProofOfValue, BacklogItem, Hypothesis, Reflection } from '../types'

declare namespace NodeJS {
  export type Timeout = number
}

const MCP_ENDPOINT = import.meta.env.VITE_MCP_ENDPOINT || 'https://mcp.ariasolutions.org'
const POLL_INTERVAL = 30000 // 30 seconds
const MAX_RECONNECT_ATTEMPTS = 10
const INITIAL_RECONNECT_DELAY = 1000 // 1 second
const MAX_RECONNECT_DELAY = 30000 // 30 seconds

type TimeoutId = number
type ConnectionStatus = DashboardState['connectionStatus']

interface ReconnectionState {
  attempts: number
  delay: number
  lastAttempt: number
}

export function useMCPConnection() {
  const [state, setState] = useState<DashboardState>({
    connectionStatus: 'connecting',
    ariaStatus: null,
    sentinels: [],
    tools: [],
    sessions: [],
    timer: null,
    risks: [],
    proofs: [],
    impulse: null,
    backlog: [],
    hypotheses: [],
    reflections: [],
    gitSummary: null,
  })

  const eventSourceRef = useRef<EventSource | null>(null)
  const pollTimersRef = useRef<Map<string, TimeoutId>>(new Map())
  const isMountedRef = useRef(true)
  const reconnectStateRef = useRef<ReconnectionState>({
    attempts: 0,
    delay: INITIAL_RECONNECT_DELAY,
    lastAttempt: 0,
  })
  const reconnectTimerRef = useRef<TimeoutId | null>(null)
  const requestQueueRef = useRef<Array<{ toolName: string; args: Record<string, unknown>; resolve: (value: unknown) => void; reject: (reason: Error) => void }>>([])
  const isOnlineRef = useRef<boolean>(typeof navigator !== 'undefined' ? navigator.onLine : true)

  const clearReconnectTimer = useCallback(() => {
    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current)
      reconnectTimerRef.current = null
    }
  }, [])

  const scheduleReconnect = useCallback(() => {
    clearReconnectTimer()
    
    const now = Date.now()
    const reconnectState = reconnectStateRef.current
    
    if (reconnectState.attempts >= MAX_RECONNECT_ATTEMPTS) {
      if (isMountedRef.current) {
        setState(prev => ({ 
          ...prev, 
          connectionStatus: 'error', 
          lastError: 'Max reconnection attempts reached. Please refresh the page.' 
        }))
      }
      return
    }

    const delay = Math.min(
      reconnectState.delay * Math.pow(2, reconnectState.attempts),
      MAX_RECONNECT_DELAY
    )

    reconnectTimerRef.current = setTimeout(() => {
      if (isMountedRef.current && isOnlineRef.current) {
        reconnectState.attempts += 1
        reconnectState.lastAttempt = Date.now()
        connect()
      }
    }, delay) as unknown as TimeoutId
  }, [clearReconnectTimer])

  const connect = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
    }

    if (!isOnlineRef.current) {
      if (isMountedRef.current) {
        setState(prev => ({ 
          ...prev, 
          connectionStatus: 'disconnected', 
          lastError: 'You are offline. Check your internet connection.' 
        }))
      }
      scheduleReconnect()
      return
    }

    if (isMountedRef.current) {
      setState(prev => ({ ...prev, connectionStatus: 'connecting', lastError: undefined }))
    }

    try {
      const es = new EventSource(`${MCP_ENDPOINT}/sse`)
      eventSourceRef.current = es

      es.onopen = () => {
        if (isMountedRef.current) {
          setState(prev => ({ ...prev, connectionStatus: 'connected', lastError: undefined }))
          reconnectStateRef.current = {
            attempts: 0,
            delay: INITIAL_RECONNECT_DELAY,
            lastAttempt: Date.now(),
          }
          flushRequestQueue()
        }
      }

      es.onerror = () => {
        if (isMountedRef.current) {
          setState(prev => ({ 
            ...prev, 
            connectionStatus: 'error', 
            lastError: 'SSE connection failed. Retrying...' 
          }))
        }
        es.close()
        eventSourceRef.current = null
        startPollingFallback()
        scheduleReconnect()
      }

      es.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data)
          handleMCPMessage(data)
        } catch {
          // Ignore parse errors
        }
      }

      es.addEventListener('tool_result', (event) => {
        try {
          const data = JSON.parse(event.data)
          handleToolResult(data)
        } catch {
          // Ignore parse errors
        }
      })
    } catch (error) {
      if (isMountedRef.current) {
        setState(prev => ({ 
          ...prev, 
          connectionStatus: 'error', 
          lastError: `Failed to create SSE connection: ${error instanceof Error ? error.message : 'Unknown error'}` 
        }))
      }
      scheduleReconnect()
    }
  }, [scheduleReconnect])

  const startPollingFallback = useCallback(() => {
    pollTimersRef.current.forEach(timer => clearInterval(timer))
    pollTimersRef.current.clear()

    const statusTimer = setInterval(() => {
      fetchStatus()
    }, POLL_INTERVAL)
    pollTimersRef.current.set('status', statusTimer)

    fetchStatus()
  }, [])

  const fetchStatus = async () => {
    try {
      const response = await fetch(`${MCP_ENDPOINT}/aria_status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })
      const data = await response.json()
      if (isMountedRef.current && data) {
        setState(prev => ({ ...prev, ariaStatus: data }))
      }
    } catch {
      // Silently fail during polling - SSE is the primary channel
    }
  }

  const handleMCPMessage = (data: unknown) => {
    // Handle incoming MCP messages
    console.debug('MCP message:', data)
  }

  const handleToolResult = (data: { tool: string; result: unknown }) => {
    // Update relevant state based on tool
    console.debug('Tool result:', data)
  }

  const queueRequest = useCallback((toolName: string, args: Record<string, unknown>): Promise<unknown> => {
    return new Promise((resolve, reject) => {
      requestQueueRef.current.push({ toolName, args, resolve, reject })
    })
  }, [])

  const flushRequestQueue = useCallback(() => {
    const queue = requestQueueRef.current
    requestQueueRef.current = []
    
    queue.forEach(({ toolName, args, resolve, reject }) => {
      callTool(toolName, args)
        .then(resolve)
        .catch(reject)
    })
  }, [])

  const callTool = useCallback(async (toolName: string, args: Record<string, unknown> = {}): Promise<unknown> => {
    if (state.connectionStatus === 'disconnected' || state.connectionStatus === 'error') {
      return queueRequest(toolName, args)
    }

    try {
      const response = await fetch(`${MCP_ENDPOINT}/${toolName}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(args),
      })
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`)
      }
      return await response.json()
    } catch (err) {
      console.error(`Tool ${toolName} failed:`, err)
      throw err instanceof Error ? err : new Error(String(err))
    }
  }, [state.connectionStatus, queueRequest])

  const refreshSentinels = useCallback(async () => {
    const data = await callTool('aria_status') as Record<string, unknown> | null
    if (data?.sentinel_count) {
      const healthResponse = await fetch(`${MCP_ENDPOINT}/aria_status`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({}),
      })
      const health = await healthResponse.json()
      setState(prev => ({ ...prev, sentinels: transformHealth(health) }))
    }
  }, [callTool])

  const refreshTools = useCallback(async () => {
    // Tools are static, but we can fetch from MCP
    // For now, use static list from types
  }, [])

  const refreshSessions = useCallback(async () => {
    const data = await callTool('task_backlog')
    // Transform to sessions
  }, [callTool])

  const refreshTimer = useCallback(async () => {
    // Timer state from Aria
  }, [])

  const refreshRisks = useCallback(async () => {
    const data = await callTool('risk_register')
    if (data) {
      setState(prev => ({ ...prev, risks: transformRisks(data) } as DashboardState))
    }
  }, [callTool])

  const refreshProofs = useCallback(async () => {
    const data = await callTool('value_proof_history')
    if (data) {
      setState(prev => ({ ...prev, proofs: transformProofs(data) } as DashboardState))
    }
  }, [callTool])

  const refreshImpulse = useCallback(async () => {
    const data = await callTool('institutional_impulse_check')
    if (data) {
      setState(prev => ({ ...prev, impulse: data as DashboardState['impulse'] }))
    }
  }, [callTool])

  const refreshBacklog = useCallback(async () => {
    const data = await callTool('task_backlog')
    if (data) {
      setState(prev => ({ ...prev, backlog: transformBacklog(data) } as DashboardState))
    }
  }, [callTool])

  const refreshHypotheses = useCallback(async () => {
    const data = await callTool('hypothesis_queue')
    if (data) {
      setState(prev => ({ ...prev, hypotheses: transformHypotheses(data) } as DashboardState))
    }
  }, [callTool])

  const refreshReflections = useCallback(async () => {
    const data = await callTool('recent_reflections')
    if (data) {
      setState(prev => ({ ...prev, reflections: transformReflections(data) } as DashboardState))
    }
  }, [callTool])

  const refreshGitSummary = useCallback(async () => {
    const data = await callTool('git_week_summary')
    if (data) {
      setState(prev => ({ ...prev, gitSummary: data as DashboardState['gitSummary'] }))
    }
  }, [callTool])

  const refreshAll = useCallback(async () => {
    await Promise.all([
      refreshSentinels(),
      refreshSessions(),
      refreshTimer(),
      refreshRisks(),
      refreshProofs(),
      refreshImpulse(),
      refreshBacklog(),
      refreshHypotheses(),
      refreshReflections(),
      refreshGitSummary(),
    ])
  }, [
    refreshSentinels,
    refreshSessions,
    refreshTimer,
    refreshRisks,
    refreshProofs,
    refreshImpulse,
    refreshBacklog,
    refreshHypotheses,
    refreshReflections,
    refreshGitSummary,
  ])

  // Initialize connection
  useEffect(() => {
    isMountedRef.current = true
    isOnlineRef.current = typeof navigator !== 'undefined' ? navigator.onLine : true

    connect()

    const handleOnline = () => {
      isOnlineRef.current = true
      if (isMountedRef.current) {
        connect()
      }
    }

    const handleOffline = () => {
      isOnlineRef.current = false
      if (isMountedRef.current) {
        setState(prev => ({ 
          ...prev, 
          connectionStatus: 'disconnected', 
          lastError: 'You are offline. Check your internet connection.' 
        }))
      }
      clearReconnectTimer()
    }

    window.addEventListener('online', handleOnline)
    window.addEventListener('offline', handleOffline)

    return () => {
      isMountedRef.current = false
      window.removeEventListener('online', handleOnline)
      window.removeEventListener('offline', handleOffline)
      clearReconnectTimer()
      
      if (eventSourceRef.current) {
        eventSourceRef.current.close()
        eventSourceRef.current = null
      }
      
      pollTimersRef.current.forEach(timer => clearInterval(timer))
      pollTimersRef.current.clear()
      requestQueueRef.current = []
    }
  }, [connect, clearReconnectTimer])

  return {
    ...state,
    callTool,
    refreshAll,
    refreshSentinels,
    refreshTools,
    refreshSessions,
    refreshTimer,
    refreshRisks,
    refreshProofs,
    refreshImpulse,
    refreshBacklog,
    refreshHypotheses,
    refreshReflections,
    refreshGitSummary,
  }
}

// Transform helpers
function transformHealth(data: unknown): SentinelHealth[] {
  // Transform Aria health response to SentinelHealth[]
  return []
}

function transformRisks(data: unknown): RiskItem[] {
  return []
}

function transformProofs(data: unknown): ProofOfValue[] {
  return []
}

function transformBacklog(data: unknown): BacklogItem[] {
  return []
}

function transformHypotheses(data: unknown): Hypothesis[] {
  return []
}

function transformReflections(data: unknown): Reflection[] {
  return []
}