import { createContext, useContext, type ReactNode } from 'react'
import { useMCPConnection } from '../hooks/useMCPConnection'
import type { DashboardState } from '../types'

interface MCPContextType extends DashboardState {
  refreshAll: () => Promise<void>
  callTool: (toolName: string, args?: Record<string, unknown>) => Promise<unknown>
  refreshSentinels: () => Promise<void>
  refreshTools: () => Promise<void>
  refreshSessions: () => Promise<void>
  refreshTimer: () => Promise<void>
  refreshRisks: () => Promise<void>
  refreshProofs: () => Promise<void>
  refreshImpulse: () => Promise<void>
  refreshBacklog: () => Promise<void>
  refreshHypotheses: () => Promise<void>
  refreshReflections: () => Promise<void>
  refreshGitSummary: () => Promise<void>
}

const MCPContext = createContext<MCPContextType | null>(null)

export function MCPProvider({ children }: { children: ReactNode }) {
  const mcp = useMCPConnection()
  
  return (
    <MCPContext.Provider value={mcp}>
      {children}
    </MCPContext.Provider>
  )
}

export function useMCP() {
  const context = useContext(MCPContext)
  if (!context) {
    throw new Error('useMCP must be used within an MCPProvider')
  }
  return context
}