import { ReactNode } from 'react'
import { NavLink, Outlet } from 'react-router-dom'
import { cn } from '../lib/utils'
import { 
  LayoutDashboard, ShieldCheck, Wrench, Activity, Clock, AlertTriangle, 
  Award, Zap, ListTodo, FlaskConical, BookOpen, GitBranch, Settings,
  ChevronLeft, ChevronRight, Moon, Sun, Wifi, WifiOff, AlertCircle, CheckCircle
} from 'lucide-react'
import { useMCP } from '../context/MCPContext'
import { getModeColor, getStatusColor } from '../lib/utils'

interface NavItem {
  path: string
  label: string
  icon: string
}

interface LayoutProps {
  navItems: NavItem[]
  currentPath: string
  children?: ReactNode
}

const iconMap: Record<string, React.ComponentType<{ className?: string }>> = {
  LayoutDashboard,
  ShieldCheck,
  Wrench,
  Activity,
  Clock,
  AlertTriangle,
  Award,
  Zap,
  ListTodo,
  FlaskConical,
  BookOpen,
  GitBranch,
  Settings,
}

export function Layout({ navItems, currentPath, children }: LayoutProps) {
  const { connectionStatus, timer, callTool } = useMCP()
  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)
  
  // For mobile
  const isMobile = typeof window !== 'undefined' && window.innerWidth < 1024

  return (
    <div className="min-h-screen bg-aria-950 flex">
      {/* Sidebar */}
      <aside
        className={cn(
          'fixed inset-y-0 left-0 z-50 transition-all duration-300 bg-aria-900/95 backdrop-blur-sm border-r border-aria-800',
          'flex flex-col',
          sidebarCollapsed ? 'w-16' : 'w-64',
          isMobile && !sidebarOpen ? '-translate-x-full' : 'translate-x-0'
        )}
        aria-label="Main navigation"
      >
        {/* Logo / Header */}
        <div className="flex items-center justify-between h-16 px-4 border-b border-aria-800">
          {!sidebarCollapsed && (
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-kernel-safety via-kernel-love to-kernel-flourishing flex items-center justify-center">
                <span className="text-white font-bold text-sm">A</span>
              </div>
              <div>
                <h1 className="font-semibold text-white text-sm">Aria</h1>
                <p className="text-xs text-aria-500">Sovereign Agent</p>
              </div>
            </div>
          )}
          {!isMobile && (
            <button
              onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
              className="p-1.5 rounded-lg text-aria-400 hover:text-white hover:bg-aria-800 transition-colors"
              aria-label={sidebarCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            >
              {sidebarCollapsed ? <ChevronRight className="w-5 h-5" /> : <ChevronLeft className="w-5 h-5" />}
            </button>
          )}
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto px-2 py-4 space-y-1" aria-label="Navigation">
          {navItems.map((item) => {
            const Icon = iconMap[item.icon]
            const isActive = currentPath === item.path || (item.path !== '/' && currentPath.startsWith(item.path))
            
            return (
              <NavLink
                key={item.path}
                to={item.path}
                className={cn(
                  'flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200',
                  'group relative overflow-hidden',
                  isActive
                    ? 'bg-gradient-to-r from-kernel-safety/20 to-kernel-love/20 text-white border border-kernel-safety/30'
                    : 'text-aria-400 hover:text-white hover:bg-aria-800',
                  sidebarCollapsed && 'justify-center px-0'
                )}
                aria-current={isActive ? 'page' : undefined}
                title={sidebarCollapsed ? item.label : undefined}
                onClick={() => isMobile && setSidebarOpen(false)}
              >
                <Icon className={cn('w-5 h-5 flex-shrink-0', isActive && 'text-kernel-love')} aria-hidden="true" />
                {!sidebarCollapsed && <span className="font-medium text-sm">{item.label}</span>}
              </NavLink>
            )
          })}
        </nav>

        {/* Footer - Connection Status & Kernel */}
        <div className="p-4 border-t border-aria-800 space-y-4">
          {/* Connection Status */}
          <div className={cn('flex items-center gap-2 px-2 py-2 rounded-lg', sidebarCollapsed && 'justify-center')}>
            <div className={cn(
              'w-2 h-2 rounded-full flex-shrink-0',
              connectionStatus === 'connected' && 'bg-kernel-flourishing animate-pulse',
              connectionStatus === 'connecting' && 'bg-yellow-400 animate-pulse',
              connectionStatus === 'error' && 'bg-kernel-safety',
              connectionStatus === 'disconnected' && 'bg-aria-500'
            )} />
            {!sidebarCollapsed && (
              <span className="text-xs text-aria-400 capitalize">{connectionStatus}</span>
            )}
          </div>

          {/* Kernel Reminder */}
          {!sidebarCollapsed && (
            <div className="px-2 py-3 rounded-lg bg-gradient-to-r from-kernel-safety/10 via-kernel-love/10 to-kernel-flourishing/10 border border-aria-700">
              <p className="text-xs text-aria-300 font-medium">Kernel: Safety · Love · Flourishing</p>
            </div>
          )}

          {/* Timer Status */}
          {timer && !sidebarCollapsed && (
            <div className="px-2 py-2 rounded-lg bg-aria-800/50 border border-aria-700">
              <div className="flex items-center justify-between text-xs mb-1">
                <span className={cn('font-medium', getModeColor(timer.mode))}>
                  {timer.mode.charAt(0).toUpperCase() + timer.mode.slice(1)}
                </span>
                <span className="text-aria-500">Tier {timer.trust_tier}</span>
              </div>
              <div className="w-full h-1.5 bg-aria-700 rounded-full overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-kernel-safety via-kernel-love to-kernel-flourishing transition-all duration-500"
                  style={{ width: `${((timer.total_lease_seconds - timer.lease_remaining_seconds) / timer.total_lease_seconds) * 100}%` }}
                />
              </div>
              <p className="text-xs text-aria-500 mt-1 text-right">
                {formatDuration(timer.lease_remaining_seconds)} remaining
              </p>
            </div>
          )}
        </div>
      </aside>

      {/* Mobile Overlay */}
      {isMobile && sidebarOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 lg:hidden"
          onClick={() => setSidebarOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Main Content */}
      <main
        className={cn(
          'flex-1 min-h-screen transition-all duration-300',
          'lg:pl-64',
          sidebarCollapsed && 'lg:pl-16',
          isMobile && 'lg:pl-0'
        )}
      >
        {/* Top Bar */}
        <header className="sticky top-0 z-30 h-16 bg-aria-950/95 backdrop-blur-sm border-b border-aria-800 flex items-center justify-between px-6">
          <div className="flex items-center gap-4">
            {isMobile && (
              <button
                onClick={() => setSidebarOpen(true)}
                className="p-2 rounded-lg text-aria-400 hover:text-white hover:bg-aria-800 lg:hidden"
                aria-label="Open menu"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                </svg>
              </button>
            )}
            <div className="hidden sm:block">
              <Outlet />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {/* Theme Toggle */}
            <button className="p-2 rounded-lg text-aria-400 hover:text-white hover:bg-aria-800 transition-colors" aria-label="Toggle theme">
              <Moon className="w-5 h-5" />
            </button>

            {/* Connection Indicator */}
            <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-aria-800/50 border border-aria-700">
              <div className={cn(
                'w-1.5 h-1.5 rounded-full',
                connectionStatus === 'connected' && 'bg-kernel-flourishing',
                connectionStatus === 'connecting' && 'bg-yellow-400 animate-pulse',
                connectionStatus === 'error' && 'bg-kernel-safety',
                connectionStatus === 'disconnected' && 'bg-aria-500'
              )} />
              <span className="text-xs text-aria-400 font-medium capitalize hidden sm:inline">
                {connectionStatus}
              </span>
            </div>
          </div>
        </header>

        {/* Page Content */}
        <div className="p-6 lg:p-8">
          {children || <Outlet />}
        </div>
      </main>
    </div>
  )
}

import { useState } from 'react'
import { formatDuration } from '../lib/utils'