import { cn } from '../../lib/utils'
import { forwardRef } from 'react'

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  value: number
  max?: number
  showLabel?: boolean
  variant?: 'default' | 'kernel' | 'success' | 'warning' | 'danger'
}

export const Progress = forwardRef<HTMLDivElement, ProgressProps>(
  ({ className, value, max = 100, showLabel, variant = 'default', ...props }, ref) => {
    const percentage = Math.min(Math.max((value / max) * 100, 0), 100)
    
    const variants = {
      default: 'bg-gradient-to-r from-aria-500 to-aria-400',
      kernel: 'bg-gradient-to-r from-kernel-safety via-kernel-love to-kernel-flourishing',
      success: 'bg-kernel-flourishing',
      warning: 'bg-yellow-400',
      danger: 'bg-kernel-safety',
    }

    return (
      <div ref={ref} className={cn('w-full', className)} {...props}>
        <div className="flex items-center justify-between text-xs mb-1">
          {showLabel && <span className="text-aria-400">{Math.round(percentage)}%</span>}
        </div>
        <div className="relative h-2 w-full bg-aria-800 rounded-full overflow-hidden">
          <div
            className={cn(
              'h-full rounded-full transition-all duration-500 ease-out',
              variants[variant]
            )}
            style={{ width: `${percentage}%` }}
            role="progressbar"
            aria-valuenow={value}
            aria-valuemin={0}
            aria-valuemax={max}
            aria-label={showLabel ? `${Math.round(percentage)}%` : undefined}
          />
        </div>
      </div>
    )
  }
)
Progress.displayName = 'Progress'