import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '../components/ui/Table'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { AlertTriangle, XCircle, CheckCircle, AlertCircle, Clock, Shield, RefreshCw, Plus } from 'lucide-react'
import { formatRelativeTime } from '../lib/utils'
import { useState } from 'react'

export function Risks() {
  const { risks, refreshRisks, connectionStatus } = useMCP()
  const [filter, setFilter] = useState<'all' | 'open' | 'mitigating' | 'resolved'>('all')
  const [severityFilter, setSeverityFilter] = useState<'all' | 'critical' | 'high' | 'medium' | 'low'>('all')

  const mockRisks = [
    { id: 'RISK-001', title: 'MCP SSE connection instability', severity: 'critical', status: 'open', description: 'SSE connections drop under load, causing session interruptions', mitigation: 'Implement connection pooling and automatic reconnection with exponential backoff', created_at: new Date(Date.now() - 86400000).toISOString() },
    { id: 'RISK-002', title: 'Ollama GPU memory exhaustion', severity: 'high', status: 'mitigating', description: '8GB VRAM insufficient for concurrent model + image generation', mitigation: 'Implement VRAM lock serialization and model offloading', created_at: new Date(Date.now() - 172800000).toISOString() },
    { id: 'RISK-003', title: 'Timer auto-extend race condition', severity: 'medium', status: 'open', description: 'Concurrent extend requests could double-extend lease', mitigation: 'Add distributed lock for timer extend operations', created_at: new Date(Date.now() - 259200000).toISOString() },
    { id: 'RISK-004', title: 'Subtask fallback loop', severity: 'medium', status: 'resolved', description: 'Fallback subtasks could chain infinitely', mitigation: 'Added max fallback depth of 3 with exponential backoff', created_at: new Date(Date.now() - 345600000).toISOString() },
    { id: 'RISK-005', title: 'Cloudflare tunnel authentication', severity: 'low', status: 'open', description: 'Tunnel token rotation not automated', mitigation: 'Set up scheduled token refresh via Cloudflare API', created_at: new Date(Date.now() - 432000000).toISOString() },
  ]

  const filteredRisks = mockRisks.filter(r => {
    if (filter !== 'all' && r.status !== filter) return false
    if (severityFilter !== 'all' && r.severity !== severityFilter) return false
    return true
  })

  const severityCounts = {
    critical: mockRisks.filter(r => r.severity === 'critical').length,
    high: mockRisks.filter(r => r.severity === 'high').length,
    medium: mockRisks.filter(r => r.severity === 'medium').length,
    low: mockRisks.filter(r => r.severity === 'low').length,
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Risk Register</h1>
          <p className="text-aria-400 mt-1">Known risks, mitigations, and resolution tracking</p>
        </div>
        <Button variant="primary"><Plus className="w-4 h-4 mr-2" /> Add Risk</Button>
      </div>

      {/* Severity Summary */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <Card className="bg-kernel-safety/10 border-kernel-safety/20">
          <CardContent className="flex items-center gap-4 p-4">
            <XCircle className="w-8 h-8 text-kernel-safety" />
            <div><p className="text-3xl font-bold text-kernel-safety">{severityCounts.critical}</p><p className="text-sm text-aria-400">Critical</p></div>
          </CardContent>
        </Card>
        <Card className="bg-orange-500/10 border-orange-500/20">
          <CardContent className="flex items-center gap-4 p-4">
            <AlertTriangle className="w-8 h-8 text-orange-500" />
            <div><p className="text-3xl font-bold text-orange-500">{severityCounts.high}</p><p className="text-sm text-aria-400">High</p></div>
          </CardContent>
        </Card>
        <Card className="bg-yellow-400/10 border-yellow-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <AlertCircle className="w-8 h-8 text-yellow-400" />
            <div><p className="text-3xl font-bold text-yellow-400">{severityCounts.medium}</p><p className="text-sm text-aria-400">Medium</p></div>
          </CardContent>
        </Card>
        <Card className="bg-blue-400/10 border-blue-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <Shield className="w-8 h-8 text-blue-400" />
            <div><p className="text-3xl font-bold text-blue-400">{severityCounts.low}</p><p className="text-sm text-aria-400">Low</p></div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="flex flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Status:</label>
            <select value={filter} onChange={e => setFilter(e.target.value as typeof filter)} className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white">
              <option value="all">All</option>
              <option value="open">Open</option>
              <option value="mitigating">Mitigating</option>
              <option value="resolved">Resolved</option>
            </select>
          </div>
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Severity:</label>
            <select value={severityFilter} onChange={e => setSeverityFilter(e.target.value as typeof severityFilter)} className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white">
              <option value="all">All</option>
              <option value="critical">Critical</option>
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
          </div>
          <Button variant="outline" onClick={refreshRisks} disabled={connectionStatus !== 'connected'}><RefreshCw className="w-4 h-4 mr-2" /> Refresh</Button>
        </CardContent>
      </Card>

      {/* Risks Table */}
      <Card>
        <CardContent className="p-0">
          {filteredRisks.length === 0 ? (
            <EmptyState icon={AlertTriangle} title="No risks match filters" description="Adjust filters or add a new risk." />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">Severity</TableHead>
                  <TableHead className="w-12">Status</TableHead>
                  <TableHead>Title</TableHead>
                  <TableHead>Description</TableHead>
                  <TableHead className="w-48">Created</TableHead>
                  <TableHead className="w-48">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredRisks.map(risk => (
                  <TableRow key={risk.id}>
                    <TableCell>
                      <Badge variant="severity" value={risk.severity}>{risk.severity}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant="status" value={risk.status}>{risk.status}</Badge>
                    </TableCell>
                    <TableCell className="font-medium">{risk.title}</TableCell>
                    <TableCell className="text-aria-300 max-w-md">{risk.description}</TableCell>
                    <TableCell className="text-sm text-aria-400 font-mono">{formatRelativeTime(risk.created_at)}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Button variant="ghost" size="sm" className="px-2 py-1"><Clock className="w-3 h-3" /></Button>
                        {risk.status !== 'resolved' && <Button variant="ghost" size="sm" className="px-2 py-1"><CheckCircle className="w-3 h-3" /></Button>}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Risk Detail Modal would go here */}
    </div>
  )
}