import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '../components/ui/Table'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { ListTodo, Plus, Filter, ArrowUpDown, Clock, Tag, RefreshCw } from 'lucide-react'
import { formatRelativeTime } from '../lib/utils'
import { useState } from 'react'

export function Backlog() {
  const { backlog, refreshBacklog, connectionStatus } = useMCP()
  const [filter, setFilter] = useState<'all' | 'pending' | 'in_progress' | 'done' | 'blocked'>('all')
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'created_at', direction: 'desc' })

  const mockBacklog = [
    { id: 'BACK-001', title: 'Implement Cloudflare Worker for dynamic subdomain routing', status: 'pending', priority: 'high', tags: ['infrastructure', 'cloudflare', 'worker'], created_at: new Date(Date.now() - 86400000).toISOString() },
    { id: 'BACK-002', title: 'Build Aria web dashboard with MCP integration', status: 'in_progress', priority: 'high', tags: ['frontend', 'dashboard', 'mcp'], created_at: new Date(Date.now() - 172800000).toISOString() },
    { id: 'BACK-003', title: 'Create site generator CLI for infinite subdomains', status: 'pending', priority: 'medium', tags: ['cli', 'generator', 'subdomains'], created_at: new Date(Date.now() - 259200000).toISOString() },
    { id: 'BACK-004', title: 'Add DNS management tools with Cloudflare API', status: 'pending', priority: 'medium', tags: ['dns', 'cloudflare', 'api'], created_at: new Date(Date.now() - 345600000).toISOString() },
    { id: 'BACK-005', title: 'Staging deployment scripts and verification', status: 'pending', priority: 'high', tags: ['devops', 'staging', 'deployment'], created_at: new Date(Date.now() - 432000000).toISOString() },
    { id: 'BACK-006', title: 'Configure nginx + certbot for direct SSL mode', status: 'done', priority: 'medium', tags: ['nginx', 'ssl', 'certbot'], created_at: new Date(Date.now() - 518400000).toISOString() },
    { id: 'BACK-007', title: 'Set up Cloudflare tunnel for zero-trust access', status: 'blocked', priority: 'high', tags: ['cloudflare', 'tunnel', 'zero-trust'], created_at: new Date(Date.now() - 604800000).toISOString() },
  ]

  const filteredBacklog = mockBacklog.filter(item => filter === 'all' || item.status === filter)

  const sortedBacklog = [...filteredBacklog].sort((a, b) => {
    const aVal = a[sortConfig.key as keyof typeof a]
    const bVal = b[sortConfig.key as keyof typeof b]
    if (sortConfig.direction === 'asc') return aVal > bVal ? 1 : -1
    return aVal < bVal ? 1 : -1
  })

  const statusCounts = {
    pending: mockBacklog.filter(b => b.status === 'pending').length,
    in_progress: mockBacklog.filter(b => b.status === 'in_progress').length,
    done: mockBacklog.filter(b => b.status === 'done').length,
    blocked: mockBacklog.filter(b => b.status === 'blocked').length,
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Task Backlog</h1>
          <p className="text-aria-400 mt-1">Pending, in-progress, and completed work items</p>
        </div>
        <Button variant="primary"><Plus className="w-4 h-4 mr-2" /> Add Task</Button>
      </div>

      {/* Status Summary */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <Card className="bg-blue-400/10 border-blue-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <ListTodo className="w-8 h-8 text-blue-400" />
            <div><p className="text-3xl font-bold text-blue-400">{statusCounts.pending}</p><p className="text-sm text-aria-400">Pending</p></div>
          </CardContent>
        </Card>
        <Card className="bg-yellow-400/10 border-yellow-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <Clock className="w-8 h-8 text-yellow-400" />
            <div><p className="text-3xl font-bold text-yellow-400">{statusCounts.in_progress}</p><p className="text-sm text-aria-400">In Progress</p></div>
          </CardContent>
        </Card>
        <Card className="bg-kernel-flourishing/10 border-kernel-flourishing/20">
          <CardContent className="flex items-center gap-4 p-4">
            <Tag className="w-8 h-8 text-kernel-flourishing" />
            <div><p className="text-3xl font-bold text-kernel-flourishing">{statusCounts.done}</p><p className="text-sm text-aria-400">Done</p></div>
          </CardContent>
        </Card>
        <Card className="bg-kernel-safety/10 border-kernel-safety/20">
          <CardContent className="flex items-center gap-4 p-4">
            <Filter className="w-8 h-8 text-kernel-safety" />
            <div><p className="text-3xl font-bold text-kernel-safety">{statusCounts.blocked}</p><p className="text-sm text-aria-400">Blocked</p></div>
          </CardContent>
        </Card>
      </div>

      {/* Filters & Controls */}
      <Card>
        <CardContent className="flex flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Filter:</label>
            <select value={filter} onChange={e => setFilter(e.target.value as typeof filter)} className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white">
              <option value="all">All</option>
              <option value="pending">Pending</option>
              <option value="in_progress">In Progress</option>
              <option value="done">Done</option>
              <option value="blocked">Blocked</option>
            </select>
          </div>
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Sort:</label>
            <select 
              value={`${sortConfig.key}:${sortConfig.direction}`} 
              onChange={e => {
                const [key, direction] = e.target.value.split(':')
                setSortConfig({ key, direction: direction as 'asc' | 'desc' })
              }}
              className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white"
            >
              <option value="created_at:desc">Newest First</option>
              <option value="created_at:asc">Oldest First</option>
              <option value="priority:desc">Priority High-Low</option>
              <option value="priority:asc">Priority Low-High</option>
            </select>
          </div>
          <Button variant="outline" onClick={refreshBacklog} disabled={connectionStatus !== 'connected'}><RefreshCw className="w-4 h-4 mr-2" /> Refresh</Button>
        </CardContent>
      </Card>

      {/* Backlog Table */}
      <Card>
        <CardContent className="p-0">
          {sortedBacklog.length === 0 ? (
            <EmptyState icon={ListTodo} title="No tasks match filters" description="Adjust filters or add a new task." />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-12">
                    <button onClick={() => setSortConfig(k => ({ ...k, key: 'status', direction: k.key === 'status' && k.direction === 'asc' ? 'desc' : 'asc' }))} className="flex items-center gap-1">
                      Status <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </TableHead>
                  <TableHead>Title</TableHead>
                  <TableHead className="w-24">
                    <button onClick={() => setSortConfig(k => ({ ...k, key: 'priority', direction: k.key === 'priority' && k.direction === 'asc' ? 'desc' : 'asc' }))} className="flex items-center gap-1">
                      Priority <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </TableHead>
                  <TableHead className="w-40">Tags</TableHead>
                  <TableHead className="w-40">
                    <button onClick={() => setSortConfig(k => ({ ...k, key: 'created_at', direction: k.key === 'created_at' && k.direction === 'asc' ? 'desc' : 'asc' }))} className="flex items-center gap-1">
                      Created <ArrowUpDown className="w-3 h-3" />
                    </button>
                  </TableHead>
                  <TableHead className="w-48">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedBacklog.map(item => (
                  <TableRow key={item.id}>
                    <TableCell>
                      <Badge variant="status" value={item.status}>{item.status}</Badge>
                    </TableCell>
                    <TableCell className="font-medium">{item.title}</TableCell>
                    <TableCell>
                      <Badge variant={item.priority === 'high' ? 'severity' : item.priority === 'medium' ? 'status' : 'default'} value={item.priority}>
                        {item.priority}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <div className="flex flex-wrap gap-1">
                        {item.tags.map(tag => (
                          <Badge key={tag} variant="default" className="text-xs">{tag}</Badge>
                        ))}
                      </div>
                    </TableCell>
                    <TableCell className="text-sm text-aria-400 font-mono">{formatRelativeTime(item.created_at)}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Button variant="ghost" size="sm" className="px-2 py-1" title="Start"><Clock className="w-3 h-3" /></Button>
                        <Button variant="ghost" size="sm" className="px-2 py-1" title="Edit"><Tag className="w-3 h-3" /></Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  )
}