import { cn } from '../../lib/utils'
import { forwardRef } from 'react'
import { getSeverityColor, getStatusColor } from '../../lib/utils'

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: 'default' | 'severity' | 'status' | 'tier' | 'mode'
  value?: string | number
}

export const Badge = forwardRef<HTMLSpanElement, BadgeProps>(
  ({ className, variant = 'default', value, children, ...props }, ref) => {
    let colorClass = 'bg-aria-700 text-aria-300 border-aria-600'
    
    if (variant === 'severity' && value) {
      colorClass = getSeverityColor(value as string)
    } else if (variant === 'status' && value) {
      colorClass = getStatusColor(value as string)
    } else if (variant === 'tier' && typeof value === 'number') {
      const tierColors = [
        'bg-aria-700 text-aria-300',
        'bg-blue-500/20 text-blue-400 border-blue-500/30',
        'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
        'bg-orange-500/20 text-orange-400 border-orange-500/30',
        'bg-kernel-safety/20 text-kernel-safety border-kernel-safety/30',
      ]
      colorClass = tierColors[value] || tierColors[0]
    } else if (variant === 'mode' && value) {
      const modeColors: Record<string, string> = {
        manual: 'bg-aria-700 text-aria-300 border-aria-600',
        bounded: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
        endurance: 'bg-kernel-flourishing/20 text-kernel-flourishing border-kernel-flourishing/30',
      }
      colorClass = modeColors[value as string] || modeColors.manual
    }

    return (
      <span
        ref={ref}
        className={cn(
          'inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border',
          colorClass,
          className
        )}
        {...props}
      >
        {children}
      </span>
    )
  }
)
Badge.displayName = 'Badge'