import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Button } from '../components/ui/Button'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../components/ui/Tabs'
import { MessageSquare, User, Mail, Calendar, ExternalLink } from 'lucide-react'
import { useEffect, useState } from 'react'
import { formatRelativeTime } from '../lib/utils'

type Tab = 'tickets' | 'leads' | 'pricing'

export function SupportPage() {
  const { callTool, connectionStatus } = useMCP()
  const [tickets, setTickets] = useState<any[]>([])
  const [leads, setLeads] = useState<any[]>([])
  const [pricing, setPricing] = useState<any>(null)
  const [activeTab, setActiveTab] = useState<Tab>('tickets')
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    loadData()
  }, [activeTab])

  const loadData = async () => {
    setIsLoading(true)
    try {
      if (activeTab === 'tickets') {
        const data = await callTool('support_list_tickets', { limit: 50 }) as any[]
        if (Array.isArray(data)) {
          setTickets(data)
        }
      } else if (activeTab === 'leads') {
        const data = await callTool('support_list_leads', { limit: 50 }) as any[]
        if (Array.isArray(data)) {
          setLeads(data)
        }
      } else if (activeTab === 'pricing') {
        const data = await callTool('support_get_pricing') as any
        if (data && !data.error) {
          setPricing(data)
        }
      }
    } catch (error) {
      console.error('Failed to load support data:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const getStatusBadge = (status: string) => {
    const variants: Record<string, any> = {
      open: 'status',
      new: 'mode',
      contacted: 'mode',
      closed: 'default',
    }
    return <Badge variant={variants[status] || 'default'} value={status}>{status}</Badge>
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Support</h1>
          <p className="text-aria-400 mt-1">Customer support tickets, leads, and pricing</p>
        </div>
        <Button onClick={loadData} disabled={connectionStatus !== 'connected'}>
          Refresh
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-xl bg-blue-400/10 flex items-center justify-center">
              <MessageSquare className="w-6 h-6 text-blue-400" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">{tickets.length}</p>
              <p className="text-sm text-aria-400">Total Tickets</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-xl bg-kernel-love/10 flex items-center justify-center">
              <User className="w-6 h-6 text-kernel-love" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">{leads.length}</p>
              <p className="text-sm text-aria-400">Leads Captured</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-4">
            <div className="w-12 h-12 rounded-xl bg-kernel-flourishing/10 flex items-center justify-center">
              <Mail className="w-6 h-6 text-kernel-flourishing" />
            </div>
            <div>
              <p className="text-2xl font-bold text-white">
                {pricing ? pricing.plans?.length + pricing.bots?.length : 0}
              </p>
              <p className="text-sm text-aria-400">Products</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as Tab)}>
        <TabsList>
          <TabsTrigger value="tickets">Tickets</TabsTrigger>
          <TabsTrigger value="leads">Leads</TabsTrigger>
          <TabsTrigger value="pricing">Pricing</TabsTrigger>
        </TabsList>

        <TabsContent value="tickets" className="space-y-4">
          {isLoading ? (
            <div className="space-y-4">
              {[1, 2, 3].map(i => (
                <Card key={i} className="animate-pulse">
                  <CardContent className="p-6 space-y-3">
                    <div className="h-4 bg-aria-800 rounded w-1/4"></div>
                    <div className="h-3 bg-aria-800 rounded w-3/4"></div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : tickets.length === 0 ? (
            <Card>
              <CardContent className="p-12 text-center">
                <MessageSquare className="w-12 h-12 text-aria-500 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-white mb-2">No tickets yet</h3>
                <p className="text-aria-400">Support tickets will appear here when customers reach out.</p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {tickets.map((ticket) => (
                <Card key={ticket.id} className="hover:border-aria-700 transition-colors">
                  <CardContent className="p-6">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <h3 className="font-semibold text-white">{ticket.subject}</h3>
                          {getStatusBadge(ticket.status)}
                          {ticket.priority && ticket.priority !== 'normal' && (
                            <Badge variant="severity" value={ticket.priority === 'high' ? 'critical' : 'low'}>
                              {ticket.priority}
                            </Badge>
                          )}
                        </div>
                        <p className="text-sm text-aria-300 mb-2">{ticket.message}</p>
                        <div className="flex items-center gap-4 text-xs text-aria-500">
                          <span className="flex items-center gap-1">
                            <User className="w-3 h-3" />
                            {ticket.name}
                          </span>
                          <span className="flex items-center gap-1">
                            <Mail className="w-3 h-3" />
                            {ticket.email}
                          </span>
                          <span className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            {formatRelativeTime(ticket.created_at)}
                          </span>
                        </div>
                      </div>
                      <Button variant="ghost" size="sm" onClick={() => window.open(`mailto:${ticket.email}?subject=Re: ${ticket.subject}`)}>
                        <ExternalLink className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="leads" className="space-y-4">
          {isLoading ? (
            <div className="space-y-4">
              {[1, 2, 3].map(i => (
                <Card key={i} className="animate-pulse">
                  <CardContent className="p-6 space-y-3">
                    <div className="h-4 bg-aria-800 rounded w-1/4"></div>
                    <div className="h-3 bg-aria-800 rounded w-3/4"></div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : leads.length === 0 ? (
            <Card>
              <CardContent className="p-12 text-center">
                <User className="w-12 h-12 text-aria-500 mx-auto mb-4" />
                <h3 className="text-lg font-semibold text-white mb-2">No leads yet</h3>
                <p className="text-aria-400">Leads will appear here when visitors show interest.</p>
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {leads.map((lead) => (
                <Card key={lead.id} className="hover:border-aria-700 transition-colors">
                  <CardContent className="p-6">
                    <div className="flex items-start justify-between gap-4">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-2">
                          <h3 className="font-semibold text-white">{lead.interest}</h3>
                          {getStatusBadge(lead.status)}
                        </div>
                        <div className="flex items-center gap-4 text-xs text-aria-500">
                          <span className="flex items-center gap-1">
                            <User className="w-3 h-3" />
                            {lead.name}
                          </span>
                          <span className="flex items-center gap-1">
                            <Mail className="w-3 h-3" />
                            {lead.email}
                          </span>
                          <span className="flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            {formatRelativeTime(lead.created_at)}
                          </span>
                        </div>
                      </div>
                      <Button variant="ghost" size="sm" onClick={() => window.open(`mailto:${lead.email}?subject=Re: ${lead.interest}`)}>
                        <ExternalLink className="w-4 h-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>

        <TabsContent value="pricing" className="space-y-6">
          {isLoading ? (
            <div className="space-y-4">
              {[1, 2, 3].map(i => (
                <Card key={i} className="animate-pulse">
                  <CardContent className="p-6 space-y-3">
                    <div className="h-4 bg-aria-800 rounded w-1/4"></div>
                    <div className="h-3 bg-aria-800 rounded w-3/4"></div>
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : pricing ? (
            <>
              {/* Plans */}
              <div>
                <h3 className="text-xl font-semibold text-white mb-4">Subscription Plans</h3>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {pricing.plans?.map((plan: any) => (
                    <Card key={plan.name} className="border-aria-800 hover:border-aria-700 transition-colors">
                      <CardContent className="p-6">
                        <h4 className="font-semibold text-white mb-1">{plan.name}</h4>
                        <p className="text-2xl font-bold text-kernel-love mb-3">{plan.price}</p>
                        <a
                          href={plan.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-2 text-sm text-kernel-flourishing hover:underline"
                        >
                          Stripe Link <ExternalLink className="w-3 h-3" />
                        </a>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>

              {/* Bots */}
              <div>
                <h3 className="text-xl font-semibold text-white mb-4">Individual Bots</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {pricing.bots?.map((bot: any) => (
                    <Card key={bot.name} className="border-aria-800 hover:border-aria-700 transition-colors">
                      <CardContent className="p-6">
                        <h4 className="font-semibold text-white mb-1">{bot.name}</h4>
                        <p className="text-lg font-bold text-kernel-love mb-3">{bot.price}</p>
                        <a
                          href={bot.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-2 text-sm text-kernel-flourishing hover:underline"
                        >
                          Stripe Link <ExternalLink className="w-3 h-3" />
                        </a>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            </>
          ) : (
            <Card>
              <CardContent className="p-12 text-center">
                <p className="text-aria-400">No pricing data available.</p>
              </CardContent>
            </Card>
          )}
        </TabsContent>
      </Tabs>
    </div>
  )
}

export { SupportPage as Support }