import { Link, useLocation } from 'react-router-dom'
import { cn } from '../lib/utils'
import { AriaLogo } from './AriaLogo'

const publicNavItems = [
  { path: '/', label: 'Home' },
  { path: '/services', label: 'Services' },
  { path: '/about', label: 'About' },
  { path: '/contact', label: 'Contact' },
  { path: '/dashboard', label: 'Dashboard' },
]

export function Navigation() {
  const location = useLocation()

  return (
    <header className="sticky top-0 z-50 border-b border-aria-800 bg-aria-950/95 backdrop-blur-sm">
      <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
        <Link to="/" className="flex items-center gap-3">
          <AriaLogo />
          <div className="hidden sm:block">
            <span className="font-semibold text-white">Aria</span>
            <span className="text-aria-500 text-sm ml-2">Sovereign Solutions</span>
          </div>
        </Link>

        <nav className="flex items-center gap-1" aria-label="Public navigation">
          {publicNavItems.map((item) => {
            const isActive = item.path === '/'
              ? location.pathname === '/'
              : location.pathname.startsWith(item.path)

            return (
              <Link
                key={item.path}
                to={item.path}
                className={cn(
                  'px-3 py-2 rounded-lg text-sm transition-colors',
                  isActive
                    ? 'text-white bg-aria-800'
                    : 'text-aria-400 hover:text-white hover:bg-aria-800/50'
                )}
              >
                {item.label}
              </Link>
            )
          })}
        </nav>
      </div>
    </header>
  )
}