import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Progress } from '../components/ui/Progress'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { FlaskConical, Plus, CheckCircle, XCircle, Clock, TrendingUp, Target, RefreshCw, Eye, Edit } from 'lucide-react'
import { formatRelativeTime } from '../lib/utils'
import { useState } from 'react'

export function Hypotheses() {
  const { hypotheses, refreshHypotheses, connectionStatus } = useMCP()
  const [filter, setFilter] = useState<'all' | 'open' | 'testing' | 'confirmed' | 'rejected'>('all')

  const mockHypotheses = [
    { id: 'HYP-001', statement: 'Endurance mode with auto-extend increases session completion rate by 40%', status: 'testing', evidence: ['Session 001: 12h completed', 'Session 002: 8h completed', 'Session 003: 15h completed'], confidence: 0.72, created_at: new Date(Date.now() - 86400000).toISOString() },
    { id: 'HYP-002', statement: 'Subtask fallback system prevents 90% of premature session terminations', status: 'confirmed', evidence: ['3 fallback triggers, all recovered', 'Zero sessions ended after 1 subtask since deploy'], confidence: 0.95, created_at: new Date(Date.now() - 172800000).toISOString() },
    { id: 'HYP-003', statement: 'Cloudflare tunnel reduces attack surface vs direct nginx exposure', status: 'open', evidence: ['Zero open ports on server', 'WAF at edge', 'DDoS protection included'], confidence: 0.88, created_at: new Date(Date.now() - 259200000).toISOString() },
    { id: 'HYP-004', statement: 'Dynamic subdomain routing via Worker enables infinite sites within 3,500 DNS limit', status: 'testing', evidence: ['Worker script handles *.ariasolutions.org', 'KV stores site configs (1KB each)', '100K req/day limit sufficient'], confidence: 0.65, created_at: new Date(Date.now() - 345600000).toISOString() },
    { id: 'HYP-005', statement: 'Aria dashboard MCP integration reduces context-switching for operators', status: 'open', evidence: [], confidence: 0.55, created_at: new Date(Date.now() - 432000000).toISOString() },
  ]

  const filteredHypotheses = mockHypotheses.filter(h => filter === 'all' || h.status === filter)

  const statusCounts = {
    open: mockHypotheses.filter(h => h.status === 'open').length,
    testing: mockHypotheses.filter(h => h.status === 'testing').length,
    confirmed: mockHypotheses.filter(h => h.status === 'confirmed').length,
    rejected: mockHypotheses.filter(h => h.status === 'rejected').length,
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Hypotheses</h1>
          <p className="text-aria-400 mt-1">Tracked hypotheses with evidence and confidence scoring</p>
        </div>
        <Button variant="primary"><Plus className="w-4 h-4 mr-2" /> New Hypothesis</Button>
      </div>

      {/* Status Summary */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <Card className="bg-blue-400/10 border-blue-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <FlaskConical className="w-8 h-8 text-blue-400" />
            <div><p className="text-3xl font-bold text-blue-400">{statusCounts.open}</p><p className="text-sm text-aria-400">Open</p></div>
          </CardContent>
        </Card>
        <Card className="bg-yellow-400/10 border-yellow-400/20">
          <CardContent className="flex items-center gap-4 p-4">
            <TrendingUp className="w-8 h-8 text-yellow-400" />
            <div><p className="text-3xl font-bold text-yellow-400">{statusCounts.testing}</p><p className="text-sm text-aria-400">Testing</p></div>
          </CardContent>
        </Card>
        <Card className="bg-kernel-flourishing/10 border-kernel-flourishing/20">
          <CardContent className="flex items-center gap-4 p-4">
            <CheckCircle className="w-8 h-8 text-kernel-flourishing" />
            <div><p className="text-3xl font-bold text-kernel-flourishing">{statusCounts.confirmed}</p><p className="text-sm text-aria-400">Confirmed</p></div>
          </CardContent>
        </Card>
        <Card className="bg-kernel-safety/10 border-kernel-safety/20">
          <CardContent className="flex items-center gap-4 p-4">
            <XCircle className="w-8 h-8 text-kernel-safety" />
            <div><p className="text-3xl font-bold text-kernel-safety">{statusCounts.rejected}</p><p className="text-sm text-aria-400">Rejected</p></div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="flex flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <label className="text-sm text-aria-400">Filter:</label>
            <select value={filter} onChange={e => setFilter(e.target.value as typeof filter)} className="bg-aria-800 border border-aria-700 rounded-lg px-3 py-2 text-sm text-white">
              <option value="all">All</option>
              <option value="open">Open</option>
              <option value="testing">Testing</option>
              <option value="confirmed">Confirmed</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>
          <Button variant="outline" onClick={refreshHypotheses} disabled={connectionStatus !== 'connected'}><RefreshCw className="w-4 h-4 mr-2" /> Refresh</Button>
        </CardContent>
      </Card>

      {/* Hypotheses Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredHypotheses.length === 0 ? (
          <EmptyState icon={FlaskConical} title="No hypotheses match filters" description="Adjust filters or create a new hypothesis." />
        ) : (
          filteredHypotheses.map(hypothesis => (
            <Card key={hypothesis.id} className="h-full">
              <CardContent className="h-full flex flex-col">
                <div className="flex items-start justify-between mb-3">
                  <Badge variant={hypothesis.status === 'confirmed' ? 'status' : hypothesis.status === 'rejected' ? 'severity' : hypothesis.status === 'testing' ? 'default' : 'default'} value={hypothesis.status}>
                    {hypothesis.status}
                  </Badge>
                  <div className="flex gap-1">
                    <Button variant="ghost" size="sm" className="px-2 py-1"><Eye className="w-3 h-3" /></Button>
                    <Button variant="ghost" size="sm" className="px-2 py-1"><Edit className="w-3 h-3" /></Button>
                  </div>
                </div>
                <p className="text-white font-medium mb-3 flex-1">{hypothesis.statement}</p>
                <Progress value={hypothesis.confidence * 100} max={100} variant={hypothesis.status === 'confirmed' ? 'success' : 'kernel'} showLabel className="mb-3" />
                <div className="mb-3">
                  <p className="text-xs text-aria-400 mb-1">Evidence ({hypothesis.evidence.length})</p>
                  <ul className="space-y-1">
                    {hypothesis.evidence.slice(0, 3).map((e, i) => (
                      <li key={i} className="text-xs text-aria-300 flex items-center gap-1">
                        <span className="w-1.5 h-1.5 rounded-full bg-aria-500" />
                        {e}
                      </li>
                    ))}
                    {hypothesis.evidence.length > 3 && (
                      <li className="text-xs text-aria-500">+{hypothesis.evidence.length - 3} more</li>
                    )}
                  </ul>
                </div>
                <div className="flex items-center justify-between pt-3 border-t border-aria-700 mt-auto">
                  <span className="text-xs text-aria-500">{formatRelativeTime(hypothesis.created_at)}</span>
                  <div className="flex gap-1">
                    {hypothesis.status === 'open' && <Button variant="outline" size="sm" className="px-2 py-1 text-xs">Start Testing</Button>}
                    {hypothesis.status === 'testing' && <Button variant="primary" size="sm" className="px-2 py-1 text-xs">Confirm</Button>}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))
        )}
      </div>
    </div>
  )
}