import { useState } from 'react'
import { Button } from '../../components/ui/Button'
import { Card, CardContent } from '../../components/ui/Card'
import { Mail, MessageSquare, Shield, Heart, Sprout, CheckCircle } from 'lucide-react'

type FormData = {
  name: string
  email: string
  subject: string
  message: string
}

type FormStatus = 'idle' | 'submitting' | 'success' | 'error'

export function ContactPage() {
  const [formData, setFormData] = useState<FormData>({
    name: '',
    email: '',
    subject: '',
    message: '',
  })
  const [status, setStatus] = useState<FormStatus>('idle')
  const [error, setError] = useState<string | null>(null)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setStatus('submitting')
    setError(null)

    try {
      const response = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      })

      if (!response.ok) {
        throw new Error('Failed to send message')
      }

      setStatus('success')
      setFormData({ name: '', email: '', subject: '', message: '' })
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong')
      setStatus('error')
    }
  }

  return (
    <div className="min-h-screen bg-aria-950 text-white">
      {/* Hero */}
      <section className="relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-kernel-safety/20 via-kernel-love/20 to-kernel-flourishing/20" />
        <div className="relative max-w-6xl mx-auto px-6 py-24 lg:py-32">
          <div className="max-w-3xl">
            <h1 className="text-4xl sm:text-5xl lg:text-6xl font-bold tracking-tight">
              <span className="bg-gradient-to-r from-kernel-safety via-kernel-love to-kernel-flourishing bg-clip-text text-transparent">
                Contact
              </span>
            </h1>
            <p className="mt-6 text-lg text-aria-300 max-w-2xl">
              Have a project in mind? Want to collaborate? Or just want to say hello?
              We'd love to hear from you.
            </p>
          </div>
        </div>
      </section>

      {/* Contact Form */}
      <section className="max-w-6xl mx-auto px-6 py-16">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Form */}
          <div className="lg:col-span-2">
            <Card className="border-aria-800">
              <CardContent className="p-8">
                {status === 'success' ? (
                  <div className="text-center py-12">
                    <div className="w-16 h-16 rounded-full bg-kernel-flourishing/10 border border-kernel-flourishing/20 flex items-center justify-center mx-auto mb-4">
                      <CheckCircle className="w-8 h-8 text-kernel-flourishing" />
                    </div>
                    <h2 className="text-2xl font-bold text-white mb-2">Message sent!</h2>
                    <p className="text-aria-400 mb-6">Thanks for reaching out. We'll get back to you within 24 hours.</p>
                    <Button onClick={() => setStatus('idle')} variant="secondary">Send another message</Button>
                  </div>
                ) : (
                  <form onSubmit={handleSubmit} className="space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <div>
                        <label htmlFor="name" className="block text-sm font-medium text-aria-300 mb-2">Name</label>
                        <input
                          type="text"
                          id="name"
                          required
                          value={formData.name}
                          onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                          className="w-full px-4 py-3 rounded-lg bg-aria-800/50 border border-aria-700 text-white placeholder-aria-500 focus:outline-none focus:border-aria-600 focus:ring-1 focus:ring-aria-600 transition-colors"
                          placeholder="Your name"
                        />
                      </div>
                      <div>
                        <label htmlFor="email" className="block text-sm font-medium text-aria-300 mb-2">Email</label>
                        <input
                          type="email"
                          id="email"
                          required
                          value={formData.email}
                          onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
                          className="w-full px-4 py-3 rounded-lg bg-aria-800/50 border border-aria-700 text-white placeholder-aria-500 focus:outline-none focus:border-aria-600 focus:ring-1 focus:ring-aria-600 transition-colors"
                          placeholder="you@example.com"
                        />
                      </div>
                    </div>
                    <div>
                      <label htmlFor="subject" className="block text-sm font-medium text-aria-300 mb-2">Subject</label>
                      <input
                        type="text"
                        id="subject"
                        required
                        value={formData.subject}
                        onChange={(e) => setFormData(prev => ({ ...prev, subject: e.target.value }))}
                        className="w-full px-4 py-3 rounded-lg bg-aria-800/50 border border-aria-700 text-white placeholder-aria-500 focus:outline-none focus:border-aria-600 focus:ring-1 focus:ring-aria-600 transition-colors"
                        placeholder="What's this about?"
                      />
                    </div>
                    <div>
                      <label htmlFor="message" className="block text-sm font-medium text-aria-300 mb-2">Message</label>
                      <textarea
                        id="message"
                        required
                        rows={6}
                        value={formData.message}
                        onChange={(e) => setFormData(prev => ({ ...prev, message: e.target.value }))}
                        className="w-full px-4 py-3 rounded-lg bg-aria-800/50 border border-aria-700 text-white placeholder-aria-500 focus:outline-none focus:border-aria-600 focus:ring-1 focus:ring-aria-600 transition-colors resize-y"
                        placeholder="Tell us about your project, idea, or question..."
                      />
                    </div>
                    {error && (
                      <div className="p-4 rounded-lg bg-kernel-safety/10 border border-kernel-safety/20 text-kernel-safety text-sm">
                        {error}
                      </div>
                    )}
                    <Button type="submit" size="lg" className="w-full sm:w-auto" disabled={status === 'submitting'}>
                      {status === 'submitting' ? 'Sending...' : 'Send message'}
                    </Button>
                  </form>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            <Card className="border-aria-800">
              <CardContent className="p-6">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-10 h-10 rounded-lg bg-kernel-love/10 flex items-center justify-center">
                    <Mail className="w-5 h-5 text-kernel-love" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-white">Email</h3>
                    <p className="text-sm text-aria-400">hello@ariasolutions.org</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-kernel-flourishing/10 flex items-center justify-center">
                    <MessageSquare className="w-5 h-5 text-kernel-flourishing" />
                  </div>
                  <div>
                    <h3 className="font-semibold text-white">Response time</h3>
                    <p className="text-sm text-aria-400">Within 24 hours</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card className="bg-gradient-to-br from-kernel-safety/10 via-kernel-love/10 to-kernel-flourishing/10 border-aria-700">
              <CardContent className="p-6">
                <h3 className="font-semibold text-white mb-3">Our commitment</h3>
                <ul className="space-y-3">
                  {[
                    'Every message is read by a human',
                    'No spam, no automated responses',
                    'Your data stays private and secure',
                    'We respond within 24 hours',
                  ].map((item) => (
                    <li key={item} className="flex items-start gap-2 text-sm text-aria-300">
                      <CheckCircle className="w-4 h-4 text-kernel-flourishing flex-shrink-0 mt-0.5" />
                      {item}
                    </li>
                  ))}
                </ul>
              </CardContent>
            </Card>

            <Card className="border-aria-800">
              <CardContent className="p-6">
                <h3 className="font-semibold text-white mb-3">Why reach out?</h3>
                <ul className="space-y-2 text-sm text-aria-400">
                  <li>• Custom agent development</li>
                  <li>• CI/CD pipeline setup</li>
                  <li>• Education platform content</li>
                  <li>• Business automation</li>
                  <li>• Technical consulting</li>
                  <li>• Partnership opportunities</li>
                </ul>
              </CardContent>
            </Card>
          </div>
        </div>
      </section>
    </div>
  )
}