import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell } from '../components/ui/Table'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { ShieldCheck, AlertCircle, XCircle, CheckCircle, RefreshCw, ChevronDown, ChevronUp } from 'lucide-react'
import { formatRelativeTime } from '../lib/utils'
import { useState } from 'react'

export function Sentinels() {
  const { sentinels, refreshSentinels, connectionStatus } = useMCP()
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: 'asc' | 'desc' }>({ key: 'level', direction: 'asc' })
  
  const sortedSentinels = [...sentinels].sort((a, b) => {
    const levelOrder = { error: 0, warn: 1, ok: 2 }
    const aVal = levelOrder[a.level as keyof typeof levelOrder]
    const bVal = levelOrder[b.level as keyof typeof levelOrder]
    if (sortConfig.direction === 'asc') return aVal - bVal
    return bVal - aVal
  })

  const levelCounts = {
    ok: sentinels.filter(s => s.level === 'ok').length,
    warn: sentinels.filter(s => s.level === 'warn').length,
    error: sentinels.filter(s => s.level === 'error').length,
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Sentinels</h1>
          <p className="text-aria-400 mt-1">System health monitors — Safety · Love · Flourishing guardians</p>
        </div>
        <Button variant="secondary" onClick={refreshSentinels} disabled={connectionStatus !== 'connected'}>
          <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
          Refresh
        </Button>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4">
        <Card className="bg-kernel-flourishing/10 border-kernel-flourishing/20">
          <CardContent className="text-center py-4">
            <p className="text-3xl font-bold text-kernel-flourishing">{levelCounts.ok}</p>
            <p className="text-sm text-aria-400">Healthy</p>
          </CardContent>
        </Card>
        <Card className="bg-yellow-400/10 border-yellow-400/20">
          <CardContent className="text-center py-4">
            <p className="text-3xl font-bold text-yellow-400">{levelCounts.warn}</p>
            <p className="text-sm text-aria-400">Warnings</p>
          </CardContent>
        </Card>
        <Card className="bg-kernel-safety/10 border-kernel-safety/20">
          <CardContent className="text-center py-4">
            <p className="text-3xl font-bold text-kernel-safety">{levelCounts.error}</p>
            <p className="text-sm text-aria-400">Critical</p>
          </CardContent>
        </Card>
      </div>

      {/* Sentinels Table */}
      <Card>
        <CardContent className="p-0">
          {sentinels.length === 0 ? (
            <EmptyState
              icon={ShieldCheck}
              title="No sentinel data"
              description="Connect to Aria to load sentinel health status."
              action={<Button variant="outline" size="sm" onClick={refreshSentinels}>Refresh</Button>}
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-10">Status</TableHead>
                  <TableHead>Name</TableHead>
                  <TableHead>Message</TableHead>
                  <TableHead className="w-48">Last Check</TableHead>
                  <TableHead className="w-60">Details</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedSentinels.map(sentinel => (
                  <TableRow key={sentinel.name}>
                    <TableCell>
                      <Badge variant="status" value={sentinel.level}>
                        {sentinel.level === 'ok' && <CheckCircle className="w-3 h-3" />}
                        {sentinel.level === 'warn' && <AlertCircle className="w-3 h-3" />}
                        {sentinel.level === 'error' && <XCircle className="w-3 h-3" />}
                      </Badge>
                    </TableCell>
                    <TableCell className="font-mono text-sm font-medium">{sentinel.name}</TableCell>
                    <TableCell className="text-aria-300 max-w-md truncate">{sentinel.message}</TableCell>
                    <TableCell className="text-sm text-aria-400 font-mono">{formatRelativeTime(sentinel.last_check)}</TableCell>
                    <TableCell>
                      {sentinel.details && Object.keys(sentinel.details).length > 0 && (
                        <DetailsPanel details={sentinel.details} />
                      )}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

function DetailsPanel({ details }: { details: Record<string, unknown> }) {
  const [open, setOpen] = useState(false)
  return (
    <div className="relative">
      <button onClick={() => setOpen(!open)} className="flex items-center gap-1 text-xs text-aria-400 hover:text-white">
        <span>Details</span>
        {open ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
      </button>
      {open && (
        <div className="absolute bottom-full left-0 mb-2 w-64 p-3 bg-aria-900 border border-aria-700 rounded-lg shadow-lg z-10 text-xs">
          {Object.entries(details).map(([key, value]) => (
            <div key={key} className="flex justify-between py-1 border-b border-aria-800 last:border-0">
              <span className="text-aria-400 font-mono">{key}</span>
              <span className="text-aria-300">{String(value)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { cn } from '../lib/utils'