import { Component, ReactNode } from 'react'
import { Button } from '../components/ui/Button'

interface ErrorBoundaryProps {
  fallback?: ReactNode
  children: ReactNode
}

interface ErrorBoundaryState {
  hasError: boolean
  error: Error | null
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props)
    this.state = { hasError: false, error: null }
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error }
  }

  componentDidCatch(error: Error, errorInfo: { componentStack: string }) {
    console.error('UI Error Boundary caught:', error, errorInfo)
  }

  handleReset = () => {
    this.setState({ hasError: false, error: null })
  }

  render() {
    if (this.state.hasError) {
      if (this.props.fallback) {
        return this.props.fallback
      }

      return (
        <div className="min-h-screen flex items-center justify-center bg-aria-950 p-6">
          <div className="max-w-md w-full space-y-4 text-center">
            <div className="w-16 h-16 rounded-2xl bg-kernel-safety/10 border border-kernel-safety/20 flex items-center justify-center mx-auto">
              <span className="text-3xl">⚠️</span>
            </div>
            <h1 className="text-2xl font-bold text-white">Something went wrong</h1>
            <p className="text-aria-400 text-sm">
              {this.state.error?.message || 'An unexpected error occurred in the UI.'}
            </p>
            <div className="flex items-center justify-center gap-3">
              <Button onClick={this.handleReset}>Try again</Button>
              <Button
                variant="secondary"
                onClick={() => {
                  window.location.href = '/'
                }}
              >
                Go home
              </Button>
            </div>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}