import { useState, useEffect, useRef } from 'react'
import { MessageSquare, X, Send, Minimize2, Maximize2, Loader2 } from 'lucide-react'
import { Button } from '../components/ui/Button'
import { Card } from '../components/ui/Card'
import { cn } from '../lib/utils'

interface Message {
  id: string
  type: 'user' | 'bot' | 'system'
  content: string
  timestamp: Date
  actions?: Array<{ label: string; url?: string; action?: string }>
}

export function SupportChat() {
  const [isOpen, setIsOpen] = useState(false)
  const [isMinimized, setIsMinimized] = useState(false)
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      type: 'bot',
      content: "Hey! I'm Aria's support assistant. How can I help you today?",
      timestamp: new Date(),
      actions: [
        { label: 'View Services', url: '/services' },
        { label: 'Pricing', url: '/services' },
        { label: 'Contact', url: '/contact' },
      ],
    },
  ])
  const [input, setInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  useEffect(() => {
    if (isOpen && !isMinimized) {
      inputRef.current?.focus()
    }
  }, [isOpen, isMinimized])

  const handleSend = async () => {
    if (!input.trim() || isLoading) return

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      type: 'user',
      content: input.trim(),
      timestamp: new Date(),
    }

    setMessages(prev => [...prev, userMessage])
    setInput('')
    setIsLoading(true)

    try {
      const response = await fetch('/api/support/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: userMessage.content }),
      })

      const data = await response.json()

      const botMessage: Message = {
        id: `bot-${Date.now()}`,
        type: 'bot',
        content: data.message || "I'm not sure how to help with that. Try /contact or email admin@ariasolutions.org.",
        timestamp: new Date(),
        actions: data.actions,
      }

      setMessages(prev => [...prev, botMessage])
    } catch (error) {
      const errorMessage: Message = {
        id: `error-${Date.now()}`,
        type: 'system',
        content: "Sorry, I'm having trouble connecting. Please try again or use the contact form.",
        timestamp: new Date(),
      }
      setMessages(prev => [...prev, errorMessage])
    } finally {
      setIsLoading(false)
    }
  }

  const handleAction = (action: { label: string; url?: string; action?: string }) => {
    if (action.url) {
      window.location.href = action.url
    } else if (action.action === 'create_ticket') {
      window.location.href = '/contact?ticket=true'
    }
  }

  if (!isOpen) {
    return (
      <button
        onClick={() => setIsOpen(true)}
        className={cn(
          'fixed bottom-6 right-6 z-50',
          'w-14 h-14 rounded-full',
          'bg-gradient-to-r from-kernel-safety via-kernel-love to-kernel-flourishing',
          'text-white shadow-lg hover:shadow-xl',
          'flex items-center justify-center',
          'transition-all duration-300 hover:scale-110'
        )}
        aria-label="Open support chat"
      >
        <MessageSquare className="w-6 h-6" />
      </button>
    )
  }

  return (
    <div
      className={cn(
        'fixed bottom-6 right-6 z-50',
        'w-full max-w-md',
        'transition-all duration-300',
        isMinimized ? 'h-14' : 'h-[500px]'
      )}
    >
      <Card className="h-full flex flex-col border-aria-800 shadow-2xl">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-aria-800">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-kernel-safety via-kernel-love to-kernel-flourishing flex items-center justify-center">
              <MessageSquare className="w-4 h-4 text-white" />
            </div>
            <div>
              <h3 className="font-semibold text-white text-sm">Support Chat</h3>
              <p className="text-xs text-aria-400">Always online</p>
            </div>
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => setIsMinimized(!isMinimized)}
              className="p-1.5 rounded-lg text-aria-400 hover:text-white hover:bg-aria-800 transition-colors"
              aria-label={isMinimized ? 'Maximize' : 'Minimize'}
            >
              {isMinimized ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
            </button>
            <button
              onClick={() => setIsOpen(false)}
              className="p-1.5 rounded-lg text-aria-400 hover:text-white hover:bg-aria-800 transition-colors"
              aria-label="Close chat"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Messages */}
        {!isMinimized && (
          <>
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={cn(
                    'flex',
                    msg.type === 'user' ? 'justify-end' : 'justify-start'
                  )}
                >
                  <div
                    className={cn(
                      'max-w-[80%] rounded-lg p-3',
                      msg.type === 'user'
                        ? 'bg-gradient-to-r from-kernel-safety to-kernel-love text-white'
                        : msg.type === 'system'
                        ? 'bg-kernel-safety/10 text-kernel-safety border border-kernel-safety/20'
                        : 'bg-aria-800 text-aria-100 border border-aria-700'
                    )}
                  >
                    <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                    {msg.actions && msg.actions.length > 0 && (
                      <div className="mt-2 flex flex-wrap gap-2">
                        {msg.actions.map((action, idx) => (
                          <button
                            key={idx}
                            onClick={() => handleAction(action)}
                            className="text-xs px-2 py-1 rounded bg-aria-700 text-aria-200 hover:bg-aria-600 transition-colors"
                          >
                            {action.label}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="bg-aria-800 text-aria-100 border border-aria-700 rounded-lg p-3">
                    <Loader2 className="w-4 h-4 animate-spin text-aria-400" />
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="p-4 border-t border-aria-800">
              <form
                onSubmit={(e) => {
                  e.preventDefault()
                  handleSend()
                }}
                className="flex gap-2"
              >
                <input
                  ref={inputRef}
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Type a message..."
                  className="flex-1 px-3 py-2 rounded-lg bg-aria-800/50 border border-aria-700 text-white placeholder-aria-500 focus:outline-none focus:border-aria-600 focus:ring-1 focus:ring-aria-600 transition-colors text-sm"
                  disabled={isLoading}
                />
                <Button
                  type="submit"
                  size="sm"
                  disabled={!input.trim() || isLoading}
                  className="px-3"
                >
                  {isLoading ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Send className="w-4 h-4" />
                  )}
                </Button>
              </form>
            </div>
          </>
        )}
      </Card>
    </div>
  )
}