import { useMCP } from '../context/MCPContext'
import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '../components/ui/Card'
import { Badge } from '../components/ui/Badge'
import { Button } from '../components/ui/Button'
import { EmptyState } from '../components/ui/EmptyState'
import { Award, User, Calendar, Zap, Shield, Heart, Plus, RefreshCw } from 'lucide-react'
import { formatRelativeTime } from '../lib/utils'

export function Proofs() {
  const { proofs, impulse, refreshProofs, connectionStatus } = useMCP()
  const [showModal, setShowModal] = useState(false)

  const mockProofs = [
    { id: 'proof_001', person_name: 'Sarah Chen', problem_solved: 'Automated deal monitoring for Pokemon cards', value_delivered: 'Saved 12hrs/week manual checking; caught 3 restocks', was_unprompted: true, person_is_builder: false, timestamp: new Date(Date.now() - 86400000).toISOString() },
    { id: 'proof_002', person_name: 'Marcus Johnson', problem_solved: 'Real estate lien auction analysis', value_delivered: 'Identified 2 undervalued properties; $47k potential equity', was_unprompted: false, person_is_builder: false, timestamp: new Date(Date.now() - 172800000).toISOString() },
    { id: 'proof_003', person_name: 'Kevin (Builder)', problem_solved: 'Sovereign agent architecture review', value_delivered: 'Validated kernel invariants; caught 2 authority tier violations', was_unprompted: false, person_is_builder: true, timestamp: new Date(Date.now() - 259200000).toISOString() },
  ]

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-white">Value Proofs</h1>
          <p className="text-aria-400 mt-1">Witnessed external value delivery — Proof Gate evidence</p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="primary" onClick={() => setShowModal(true)}><Plus className="w-4 h-4 mr-2" /> Record Proof</Button>
          <Button variant="outline" onClick={refreshProofs} disabled={connectionStatus !== 'connected'}><RefreshCw className="w-4 h-4 mr-2" /> Refresh</Button>
        </div>
      </div>

      {/* Proof Gate Status */}
      <Card className={cn(
        'border-2',
        impulse?.proof_gate 
          ? 'border-kernel-flourishing bg-kernel-flourishing/5' 
          : 'border-kernel-safety bg-kernel-safety/5'
      )}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Award className="w-5 h-5" style={{ color: impulse?.proof_gate ? '#22c55e' : '#ef4444' }} />
            Proof Gate: {impulse?.proof_gate ? 'MET ✓' : 'NOT MET ✗'}
          </CardTitle>
          <CardDescription>Requires ≥1 external (non-builder) value proof for institutional impulse readiness</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="p-4 rounded-lg bg-aria-800/50 text-center">
              <p className="text-3xl font-bold text-white">{mockProofs.filter(p => !p.person_is_builder).length}</p>
              <p className="text-sm text-aria-400">External Proofs</p>
            </div>
            <div className="p-4 rounded-lg bg-aria-800/50 text-center">
              <p className="text-3xl font-bold text-white">{mockProofs.length}</p>
              <p className="text-sm text-aria-400">Total Proofs</p>
            </div>
            <div className="p-4 rounded-lg bg-aria-800/50 text-center">
              <p className="text-3xl font-bold text-white">{mockProofs.filter(p => p.was_unprompted).length}</p>
              <p className="text-sm text-aria-400">Unprompted</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Proofs List */}
      <Card>
        <CardContent className="p-0">
          {mockProofs.length === 0 ? (
            <EmptyState icon={Award} title="No value proofs recorded" description="Start recording witnessed value deliveries to satisfy the Proof Gate." action={<Button variant="primary" onClick={() => setShowModal(true)}><Plus className="w-4 h-4 mr-2" /> Record First Proof</Button>} />
          ) : (
            <div className="divide-y divide-aria-800">
              {mockProofs.map(proof => (
                <div key={proof.id} className="p-6 hover:bg-aria-800/30 transition-colors">
                  <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 rounded-xl bg-kernel-love/10 flex items-center justify-center flex-shrink-0">
                        <Award className="w-6 h-6 text-kernel-love" />
                      </div>
                      <div>
                        <div className="flex items-center gap-3">
                          <h4 className="font-semibold text-white">{proof.person_name}</h4>
                          {proof.was_unprompted && <Badge variant="status" value="ok">Unprompted</Badge>}
                          {proof.person_is_builder && <Badge variant="default">Builder</Badge>}
                        </div>
                        <p className="text-aria-300 mt-1">{proof.problem_solved}</p>
                        <p className="text-kernel-flourishing text-sm mt-1 font-medium">{proof.value_delivered}</p>
                        <p className="text-xs text-aria-500 mt-2">{formatRelativeTime(proof.timestamp)}</p>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Record Proof Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80">
          <Card className="w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <CardHeader>
              <CardTitle>Record Proof of Value</CardTitle>
              <CardDescription>Document witnessed value delivery. This feeds the Institutional Impulse Proof Gate.</CardDescription>
            </CardHeader>
            <CardContent>
              <ProofForm onClose={() => setShowModal(false)} />
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  )
}

function ProofForm({ onClose }: { onClose: () => void }) {
  return (
    <form className="space-y-4" onSubmit={e => { e.preventDefault(); onClose() }}>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div>
          <label className="block text-sm text-aria-400 mb-1">Person Name *</label>
          <input type="text" className="w-full bg-aria-800 border border-aria-700 rounded-lg px-4 py-2 text-white placeholder-aria-500 focus:ring-2 focus:ring-kernel-safety/50" required />
        </div>
        <div>
          <label className="block text-sm text-aria-400 mb-1">Person is Builder?</label>
          <select className="w-full bg-aria-800 border border-aria-700 rounded-lg px-4 py-2 text-white">
            <option value="false">No (External)</option>
            <option value="true">Yes (Builder)</option>
          </select>
        </div>
      </div>
      <div>
        <label className="block text-sm text-aria-400 mb-1">Problem Solved *</label>
        <textarea rows={3} className="w-full bg-aria-800 border border-aria-700 rounded-lg px-4 py-2 text-white placeholder-aria-500 focus:ring-2 focus:ring-kernel-safety/50" required />
      </div>
      <div>
        <label className="block text-sm text-aria-400 mb-1">Value Delivered *</label>
        <textarea rows={3} className="w-full bg-aria-800 border border-aria-700 rounded-lg px-4 py-2 text-white placeholder-aria-500 focus:ring-2 focus:ring-kernel-safety/50" required />
      </div>
      <div className="flex items-center gap-2">
        <input type="checkbox" id="unprompted" className="w-4 h-4 rounded border-aria-600 text-kernel-safety focus:ring-kernel-safety" />
        <label htmlFor="unprompted" className="text-sm text-aria-300">Was unprompted (Aria noticed and helped without being asked)</label>
      </div>
      <div className="flex justify-end gap-3 pt-4 border-t border-aria-700">
        <Button variant="outline" onClick={onClose}>Cancel</Button>
        <Button variant="primary" type="submit"><Award className="w-4 h-4 mr-2" /> Record Proof</Button>
      </div>
    </form>
  )
}

import { useState } from 'react'
import { cn } from '../lib/utils'